"""Karnataka PUC biology practicals: slide and specimen study (drawn
microscope views and museum specimens), urine and water tests, plasmolysis,
respiration and the quadrat method. Written for KINETIX; reviewed=False until
a subject teacher checks."""


def add(lab, W, Q):
    puc1 = dict(subject='Biology', domain='biology', levels=[11], curricula=['ka-puc', 'cbse', 'ncert'])
    puc2 = dict(subject='Biology', domain='biology', levels=[12], curricula=['ka-puc', 'cbse', 'ncert'])
    MICRO = W('Compound microscope', 'संयुक्त सूक्ष्मदर्शी', 'ಸಂಯುಕ್ತ ಸೂಕ್ಷ್ಮದರ್ಶಕ')
    SLIDES = W('Permanent slides', 'स्थायी स्लाइडें', 'ಶಾಶ್ವತ ಸ್ಲೈಡ್‌ಗಳು')
    SPEC = W('Preserved specimens and charts', 'परिरक्षित नमूने और चार्ट', 'ಸಂರಕ್ಷಿತ ಮಾದರಿಗಳು ಮತ್ತು ಚಾರ್ಟ್‌ಗಳು')
    RECORD = W('Record book and pencil', 'अभिलेख पुस्तिका और पेंसिल', 'ದಾಖಲೆ ಪುಸ್ತಕ ಮತ್ತು ಪೆನ್ಸಿಲ್')
    STUDY_STEPS = [
        W('Focus each slide under low power first, then high power; look at specimens from all sides.', 'हर स्लाइड को पहले कम आवर्धन पर, फिर अधिक आवर्धन पर फ़ोकस करें; नमूनों को सभी ओर से देखें।', 'ಪ್ರತಿ ಸ್ಲೈಡನ್ನು ಮೊದಲು ಕಡಿಮೆ ವರ್ಧನೆಯಲ್ಲಿ, ನಂತರ ಹೆಚ್ಚಿನ ವರ್ಧನೆಯಲ್ಲಿ ಫೋಕಸ್ ಮಾಡಿ; ಮಾದರಿಗಳನ್ನು ಎಲ್ಲಾ ಕಡೆಯಿಂದ ನೋಡಿ.'),
        W('Find the identifying features and switch on the labels to check.', 'पहचान के लक्षण ढूँढें और जाँचने के लिए नामांकन चालू करें।', 'ಗುರುತಿಸುವ ಲಕ್ಷಣಗಳನ್ನು ಕಂಡುಹಿಡಿದು ಪರಿಶೀಲಿಸಲು ಲೇಬಲ್‌ಗಳನ್ನು ಆನ್ ಮಾಡಿ.'),
        W('Draw a neat labelled diagram of each in your record.', 'अपने अभिलेख में प्रत्येक का साफ़ नामांकित चित्र बनाएँ।', 'ನಿಮ್ಮ ದಾಖಲೆಯಲ್ಲಿ ಪ್ರತಿಯೊಂದರ ಅಚ್ಚುಕಟ್ಟಾದ ಲೇಬಲ್ ಚಿತ್ರ ಬಿಡಿಸಿ.'),
        W('Write its classification (or what it shows) and record it.', 'उसका वर्गीकरण (या वह क्या दिखाता है) लिखें और दर्ज करें।', 'ಅದರ ವರ್ಗೀಕರಣ (ಅಥವಾ ಅದು ತೋರಿಸುವುದು) ಬರೆದು ದಾಖಲಿಸಿ.'),
        W('Compare the specimens and note how they differ.', 'नमूनों की तुलना करें और अंतर लिखें।', 'ಮಾದರಿಗಳನ್ನು ಹೋಲಿಸಿ ವ್ಯತ್ಯಾಸಗಳನ್ನು ಬರೆಯಿರಿ.'),
    ]
    STUDY_PRE = [W('Never focus downwards with the coarse knob under high power.', 'अधिक आवर्धन पर मोटे नॉब से कभी नीचे की ओर फ़ोकस न करें।', 'ಹೆಚ್ಚಿನ ವರ್ಧನೆಯಲ್ಲಿ ಒರಟು ಗುಬ್ಬಿಯಿಂದ ಎಂದೂ ಕೆಳಮುಖವಾಗಿ ಫೋಕಸ್ ಮಾಡಬೇಡಿ.'), W('Handle slides by their edges and preserved specimens with care.', 'स्लाइडों को किनारों से और परिरक्षित नमूनों को सावधानी से पकड़ें।', 'ಸ್ಲೈಡ್‌ಗಳನ್ನು ಅಂಚುಗಳಿಂದ, ಸಂರಕ್ಷಿತ ಮಾದರಿಗಳನ್ನು ಜಾಗ್ರತೆಯಿಂದ ಹಿಡಿಯಿರಿ.'), W('Draw what you see, not what the textbook shows.', 'जो दिखे वही बनाएँ, पाठ्यपुस्तक वाला नहीं।', 'ಪಠ್ಯಪುಸ್ತಕದ್ದಲ್ಲ, ನೀವು ಕಾಣುವುದನ್ನು ಬಿಡಿಸಿ.')]

    def study(lid, kit, base, keywords, title, summary, aim, principle, conclusion, viva, apparatus=None):
        lab(id=lid, bench='specimens', setup={'kit': kit}, **base, keywords=keywords, title=title, summary=summary, aim=aim, principle=principle,
            apparatus=apparatus or [MICRO, SLIDES, SPEC, RECORD], steps=STUDY_STEPS, precautions=STUDY_PRE, conclusion=conclusion, viva=viva)

    study('diversity-plants', 'diversity-plants', puc1,
          ['biological classification', 'plant kingdom', 'diversity', 'monera', 'fungi', 'algae', 'bryophytes', 'pteridophytes', 'gymnosperms', 'spirogyra', 'rhizopus', 'specimens'],
          W('Diversity: microbes, fungi and plants', 'विविधता: सूक्ष्मजीव, कवक और पादप', 'ವೈವಿಧ್ಯ: ಸೂಕ್ಷ್ಮಜೀವಿಗಳು, ಶಿಲೀಂಧ್ರಗಳು ಮತ್ತು ಸಸ್ಯಗಳು'),
          W('Study bacteria, Spirogyra, Rhizopus, yeast, a mushroom, a moss, a fern and Pinus, and place each in its group.', 'बैक्टीरिया, स्पाइरोगायरा, राइज़ोपस, यीस्ट, मशरूम, मॉस, फ़र्न और पाइनस का अध्ययन करें और प्रत्येक को उसके समूह में रखें।', 'ಬ್ಯಾಕ್ಟೀರಿಯಾ, ಸ್ಪೈರೋಗೈರಾ, ರೈಜೋಪಸ್, ಯೀಸ್ಟ್, ಅಣಬೆ, ಪಾಚಿ, ಜರೀಗಿಡ ಮತ್ತು ಪೈನಸ್ ಅಧ್ಯಯನ ಮಾಡಿ ಪ್ರತಿಯೊಂದನ್ನು ಅದರ ಗುಂಪಿಗೆ ಸೇರಿಸಿ.'),
          W('To study and identify specimens and slides of bacteria, algae, fungi, bryophytes, pteridophytes and gymnosperms, giving reasons.', 'बैक्टीरिया, शैवाल, कवक, ब्रायोफ़ाइट, टेरिडोफ़ाइट और जिम्नोस्पर्म के नमूनों और स्लाइडों का अध्ययन कर कारण सहित पहचान करना।', 'ಬ್ಯಾಕ್ಟೀರಿಯಾ, ಶೈವಲ, ಶಿಲೀಂಧ್ರ, ಬ್ರಯೋಫೈಟ್, ಟೆರಿಡೋಫೈಟ್ ಮತ್ತು ಜಿಮ್ನೋಸ್ಪರ್ಮ್‌ಗಳ ಮಾದರಿ ಮತ್ತು ಸ್ಲೈಡ್‌ಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಕಾರಣ ಸಹಿತ ಗುರುತಿಸುವುದು.'),
          W('Organisms are grouped by cell type (prokaryotic or eukaryotic), body organisation (unicellular, filament, thallus, leafy, vascular), mode of nutrition and how they reproduce (spores, seeds).', 'जीवों को कोशिका प्रकार (प्रोकैरियोटी या यूकैरियोटी), शरीर संगठन (एककोशिकीय, तंतु, सूकाय, पत्तीदार, संवहनी), पोषण विधि और जनन विधि (बीजाणु, बीज) से वर्गीकृत किया जाता है।', 'ಜೀವಿಗಳನ್ನು ಕೋಶ ಪ್ರಕಾರ (ಪ್ರೊಕ್ಯಾರಿಯೋಟ್ ಅಥವಾ ಯುಕ್ಯಾರಿಯೋಟ್), ದೇಹ ಸಂಘಟನೆ (ಏಕಕೋಶೀಯ, ತಂತು, ಥ್ಯಾಲಸ್, ಎಲೆಯುಳ್ಳ, ನಾಳೀಯ), ಪೋಷಣೆಯ ವಿಧಾನ ಮತ್ತು ಸಂತಾನೋತ್ಪತ್ತಿ (ಬೀಜಕ, ಬೀಜ) ಆಧಾರದಲ್ಲಿ ವರ್ಗೀಕರಿಸಲಾಗುತ್ತದೆ.'),
          W('Each organism fits its group by visible features: no nucleus in bacteria, spiral chloroplasts in Spirogyra, sporangia in Rhizopus, a sporophyte on the moss, sori on the fern and naked seeds in cones of Pinus.', 'प्रत्येक जीव दिखने वाले लक्षणों से अपने समूह में आता है: बैक्टीरिया में केंद्रक नहीं, स्पाइरोगायरा में सर्पिल हरितलवक, राइज़ोपस में बीजाणुधानी, मॉस पर बीजाणुद्भिद, फ़र्न पर सोरस और पाइनस के शंकुओं में नग्न बीज।', 'ಪ್ರತಿ ಜೀವಿ ಕಾಣುವ ಲಕ್ಷಣಗಳಿಂದ ತನ್ನ ಗುಂಪಿಗೆ ಸೇರುತ್ತದೆ: ಬ್ಯಾಕ್ಟೀರಿಯಾದಲ್ಲಿ ಕೋಶಕೇಂದ್ರವಿಲ್ಲ, ಸ್ಪೈರೋಗೈರಾದಲ್ಲಿ ಸುರುಳಿ ಹರಿತ್ತಿಲವು, ರೈಜೋಪಸ್‌ನಲ್ಲಿ ಬೀಜಕಧಾನಿ, ಪಾಚಿಯ ಮೇಲೆ ಬೀಜಕೋದ್ಭಿದ, ಜರೀಗಿಡದಲ್ಲಿ ಸೋರಸ್, ಪೈನಸ್ ಶಂಕುಗಳಲ್ಲಿ ನಗ್ನ ಬೀಜಗಳು.'),
          [Q(W('Why is Rhizopus a fungus and not a plant?', 'राइज़ोपस कवक है, पादप नहीं, क्यों?', 'ರೈಜೋಪಸ್ ಸಸ್ಯವಲ್ಲ, ಶಿಲೀಂಧ್ರ ಏಕೆ?'), W('It has no chlorophyll and feeds on dead matter (saprophyte); its wall is chitin.', 'इसमें पर्णहरित नहीं है और यह मृत पदार्थ पर पलता है (मृतोपजीवी); इसकी भित्ति काइटिन की है।', 'ಅದರಲ್ಲಿ ಪತ್ರಹರಿತ್ತಿಲ್ಲ, ಸತ್ತ ವಸ್ತುವಿನ ಮೇಲೆ ಬದುಕುತ್ತದೆ (ಕೊಳೆತಿನಿ); ಗೋಡೆ ಕೈಟಿನ್.')),
           Q(W('What is the dominant phase in a moss?', 'मॉस में प्रभावी अवस्था कौन सी है?', 'ಪಾಚಿಯಲ್ಲಿ ಪ್ರಧಾನ ಹಂತ ಯಾವುದು?'), W('The haploid gametophyte; the sporophyte depends on it.', 'अगुणित युग्मकोद्भिद; बीजाणुद्भिद उस पर निर्भर रहता है।', 'ಏಕಗುಣಿತ ಯುಗ್ಮಕೋದ್ಭಿದ; ಬೀಜಕೋದ್ಭಿದ ಅದರ ಮೇಲೆ ಅವಲಂಬಿತ.')),
           Q(W('Why are ferns called vascular cryptogams?', 'फ़र्न को संवहनी क्रिप्टोगैम क्यों कहते हैं?', 'ಜರೀಗಿಡಗಳನ್ನು ನಾಳೀಯ ಕ್ರಿಪ್ಟೊಗ್ಯಾಮ್ ಎಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?'), W('They have xylem and phloem but bear no flowers or seeds.', 'उनमें जाइलम और फ़्लोएम हैं पर फूल या बीज नहीं।', 'ಅವುಗಳಲ್ಲಿ ಕ್ಸೈಲಮ್ ಮತ್ತು ಫ್ಲೋಯಮ್ ಇವೆ, ಆದರೆ ಹೂವು ಅಥವಾ ಬೀಜ ಇಲ್ಲ.')),
           Q(W('What does “gymnosperm” mean?', '“जिम्नोस्पर्म” का क्या अर्थ है?', '“ಜಿಮ್ನೋಸ್ಪರ್ಮ್” ಅರ್ಥವೇನು?'), W('Naked seed: the ovules are not enclosed in an ovary.', 'नग्न बीज: बीजांड अंडाशय में बंद नहीं होते।', 'ನಗ್ನ ಬೀಜ: ಅಂಡಕಗಳು ಅಂಡಾಶಯದಲ್ಲಿ ಆವೃತವಾಗಿಲ್ಲ.')),
           Q(W('How does yeast reproduce?', 'यीस्ट कैसे जनन करता है?', 'ಯೀಸ್ಟ್ ಹೇಗೆ ಸಂತಾನೋತ್ಪತ್ತಿ ಮಾಡುತ್ತದೆ?'), W('Asexually by budding.', 'मुकुलन द्वारा अलैंगिक रूप से।', 'ಮೊಗ್ಗುವಿಕೆಯಿಂದ ಅಲೈಂಗಿಕವಾಗಿ.'))])

    study('diversity-animals', 'diversity-animals', puc1,
          ['animal kingdom', 'diversity', 'protista', 'non-chordates', 'chordates', 'amoeba', 'paramecium', 'hydra', 'earthworm', 'cockroach', 'specimens', 'phylum'],
          W('Diversity: protists and animals', 'विविधता: प्रोटिस्ट और जंतु', 'ವೈವಿಧ್ಯ: ಪ್ರೋಟಿಸ್ಟ್‌ಗಳು ಮತ್ತು ಪ್ರಾಣಿಗಳು'),
          W('Study Amoeba, Paramecium, Hydra, liver fluke, Ascaris, earthworm, cockroach, starfish and rohu, and name each one’s phylum.', 'अमीबा, पैरामीशियम, हाइड्रा, यकृत कृमि, ऐस्केरिस, केंचुआ, तिलचट्टा, तारामछली और रोहू का अध्ययन करें और प्रत्येक का संघ बताएँ।', 'ಅಮೀಬಾ, ಪ್ಯಾರಮೀಸಿಯಂ, ಹೈಡ್ರಾ, ಯಕೃತ್ ಹುಳು, ಆಸ್ಕರಿಸ್, ಎರೆಹುಳು, ಜಿರಳೆ, ನಕ್ಷತ್ರಮೀನು ಮತ್ತು ರೋಹು ಅಧ್ಯಯನ ಮಾಡಿ ಪ್ರತಿಯೊಂದರ ವಂಶ ಹೆಸರಿಸಿ.'),
          W('To study and identify specimens of protists and animals from different phyla, giving reasons.', 'विभिन्न संघों के प्रोटिस्ट और जंतुओं के नमूनों का अध्ययन कर कारण सहित पहचान करना।', 'ಬೇರೆ ಬೇರೆ ವಂಶಗಳ ಪ್ರೋಟಿಸ್ಟ್ ಮತ್ತು ಪ್ರಾಣಿಗಳ ಮಾದರಿಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಕಾರಣ ಸಹಿತ ಗುರುತಿಸುವುದು.'),
          W('Animals are classified by levels of organisation, symmetry, body cavity, segmentation and the presence of a notochord.', 'जंतुओं का वर्गीकरण संगठन के स्तर, सममिति, देहगुहा, खंडीभवन और पृष्ठरज्जु की उपस्थिति से होता है।', 'ಪ್ರಾಣಿಗಳನ್ನು ಸಂಘಟನೆಯ ಮಟ್ಟ, ಸಮಮಿತಿ, ದೇಹಕುಹರ, ಖಂಡೀಕರಣ ಮತ್ತು ನೋಟೋಕಾರ್ಡ್ ಇರುವಿಕೆ ಆಧಾರದಲ್ಲಿ ವರ್ಗೀಕರಿಸಲಾಗುತ್ತದೆ.'),
          W('Each specimen shows the key features of its phylum: pseudopodia or cilia in protists, tentacles in cnidarians, a flat body in flatworms, segments in annelids, jointed legs in arthropods, radial arms in echinoderms and gills and fins in fishes.', 'प्रत्येक नमूना अपने संघ के मुख्य लक्षण दिखाता है: प्रोटिस्ट में कूटपाद या पक्ष्माभ, निडेरिया में स्पर्शक, चपटे कृमियों में चपटा शरीर, ऐनेलिडा में खंड, आर्थ्रोपोडा में संधियुक्त पाद, इकाइनोडर्मेटा में अरीय भुजाएँ और मछलियों में गलफड़े व पख।', 'ಪ್ರತಿ ಮಾದರಿ ತನ್ನ ವಂಶದ ಮುಖ್ಯ ಲಕ್ಷಣ ತೋರುತ್ತದೆ: ಪ್ರೋಟಿಸ್ಟ್‌ಗಳಲ್ಲಿ ಮಿಥ್ಯಾಪಾದ ಅಥವಾ ಸಿಲಿಯ, ಸೀಲೆಂಟರೇಟ್‌ಗಳಲ್ಲಿ ಸ್ಪರ್ಶಾಂಗ, ಚಪ್ಪಟೆ ಹುಳುಗಳಲ್ಲಿ ಚಪ್ಪಟೆ ದೇಹ, ಅನೆಲಿಡಾದಲ್ಲಿ ಖಂಡಗಳು, ಸಂಧಿಪದಿಗಳಲ್ಲಿ ಕೀಲುಳ್ಳ ಕಾಲುಗಳು, ಕಂಟಕಚರ್ಮಿಗಳಲ್ಲಿ ತ್ರಿಜ್ಯ ತೋಳುಗಳು, ಮೀನುಗಳಲ್ಲಿ ಕಿವಿರು ಮತ್ತು ಈಜುರೆಕ್ಕೆಗಳು.'),
          [Q(W('How does Paramecium move?', 'पैरामीशियम कैसे चलता है?', 'ಪ್ಯಾರಮೀಸಿಯಂ ಹೇಗೆ ಚಲಿಸುತ್ತದೆ?'), W('By beating its cilia.', 'अपने पक्ष्माभ हिलाकर।', 'ಸಿಲಿಯಗಳನ್ನು ಬಡಿದು.')),
           Q(W('What are the stinging cells of Hydra called?', 'हाइड्रा की दंश कोशिकाएँ क्या कहलाती हैं?', 'ಹೈಡ್ರಾದ ಕುಟುಕು ಕೋಶಗಳನ್ನು ಏನೆನ್ನುತ್ತಾರೆ?'), W('Cnidoblasts (nematocysts).', 'निडोब्लास्ट (नेमैटोसिस्ट)।', 'ನಿಡೋಬ್ಲಾಸ್ಟ್‌ಗಳು (ನೆಮಟೋಸಿಸ್ಟ್).')),
           Q(W('What is the clitellum of an earthworm for?', 'केंचुए का क्लाइटेलम किसलिए है?', 'ಎರೆಹುಳುವಿನ ಕ್ಲೈಟೆಲಮ್ ಯಾವುದಕ್ಕೆ?'), W('It forms the cocoon in which eggs are laid.', 'यह कोकून बनाता है जिसमें अंडे दिए जाते हैं।', 'ಮೊಟ್ಟೆ ಇಡುವ ಕೋಶ (ಕೊಕೂನ್) ರೂಪಿಸುತ್ತದೆ.')),
           Q(W('What kind of symmetry does an adult starfish show?', 'वयस्क तारामछली कैसी सममिति दिखाती है?', 'ವಯಸ್ಕ ನಕ್ಷತ್ರಮೀನು ಯಾವ ಸಮಮಿತಿ ತೋರುತ್ತದೆ?'), W('Radial (five-part) symmetry.', 'अरीय (पंचतयी) सममिति।', 'ತ್ರಿಜ್ಯ (ಐದು ಭಾಗದ) ಸಮಮಿತಿ.')),
           Q(W('Which phylum has the largest number of species?', 'किस संघ में सबसे अधिक जातियाँ हैं?', 'ಯಾವ ವಂಶದಲ್ಲಿ ಅತಿ ಹೆಚ್ಚು ಪ್ರಭೇದಗಳಿವೆ?'), W('Arthropoda.', 'आर्थ्रोपोडा।', 'ಆರ್ಥ್ರೋಪೋಡಾ.'))])

    study('plant-anatomy', 'plant-anatomy', puc1,
          ['anatomy of flowering plants', 'transverse section', 'dicot stem', 'monocot stem', 'dicot root', 'monocot root', 'dicot leaf', 'vascular bundle', 'xylem', 'phloem'],
          W('T.S. of dicot and monocot stems, roots and a leaf', 'द्विबीजपत्री और एकबीजपत्री तने, जड़ और पत्ती की अनुप्रस्थ काट', 'ದ್ವಿದಳ ಮತ್ತು ಏಕದಳ ಕಾಂಡ, ಬೇರು ಮತ್ತು ಎಲೆಯ ಅಡ್ಡಛೇದ'),
          W('Compare stained sections of stems, roots and a leaf: how the vascular bundles are arranged tells them apart.', 'तनों, जड़ों और पत्ती की अभिरंजित काटों की तुलना करें: संवहन पूलों की व्यवस्था उन्हें अलग बताती है।', 'ಕಾಂಡ, ಬೇರು ಮತ್ತು ಎಲೆಯ ಬಣ್ಣಹಾಕಿದ ಛೇದಗಳನ್ನು ಹೋಲಿಸಿ: ನಾಳೀಯ ಕಟ್ಟುಗಳ ಜೋಡಣೆ ಅವುಗಳನ್ನು ಬೇರ್ಪಡಿಸುತ್ತದೆ.'),
          W('To study transverse sections of dicot and monocot stems and roots and a vertical section of a dicot leaf.', 'द्विबीजपत्री और एकबीजपत्री तनों और जड़ों की अनुप्रस्थ काट तथा द्विबीजपत्री पत्ती की ऊर्ध्वाधर काट का अध्ययन करना।', 'ದ್ವಿದಳ ಮತ್ತು ಏಕದಳ ಕಾಂಡ ಹಾಗೂ ಬೇರುಗಳ ಅಡ್ಡಛೇದ ಮತ್ತು ದ್ವಿದಳ ಎಲೆಯ ಲಂಬಛೇದ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
          W('Stems have conjoint bundles (xylem and phloem together): in a ring and open in dicots, scattered and closed in monocots. Roots have radial bundles: 2–4 xylem groups in dicots, many in monocots. A dicot leaf is dorsiventral.', 'तनों में संयुक्त पूल होते हैं (जाइलम और फ़्लोएम साथ): द्विबीजपत्री में वलय में और खुले, एकबीजपत्री में बिखरे और बंद। जड़ों में अरीय पूल होते हैं: द्विबीजपत्री में 2–4 जाइलम समूह, एकबीजपत्री में अनेक। द्विबीजपत्री पत्ती पृष्ठाधारी होती है।', 'ಕಾಂಡಗಳಲ್ಲಿ ಸಂಯುಕ್ತ ಕಟ್ಟುಗಳು (ಕ್ಸೈಲಮ್ ಮತ್ತು ಫ್ಲೋಯಮ್ ಒಟ್ಟಿಗೆ): ದ್ವಿದಳದಲ್ಲಿ ಉಂಗುರದಲ್ಲಿ ಮತ್ತು ತೆರೆದ, ಏಕದಳದಲ್ಲಿ ಚದುರಿದ ಮತ್ತು ಮುಚ್ಚಿದ. ಬೇರುಗಳಲ್ಲಿ ತ್ರಿಜ್ಯ ಕಟ್ಟುಗಳು: ದ್ವಿದಳದಲ್ಲಿ 2–4 ಕ್ಸೈಲಮ್ ಗುಂಪು, ಏಕದಳದಲ್ಲಿ ಹಲವು. ದ್ವಿದಳ ಎಲೆ ಪೃಷ್ಠಾಧರ.'),
          W('The sections are told apart by their bundles: a ring in the dicot stem, scattered in the monocot stem, few radial xylem groups in the dicot root and many in the monocot root; the leaf shows palisade above and spongy tissue below.', 'काटें अपने पूलों से पहचानी जाती हैं: द्विबीजपत्री तने में वलय, एकबीजपत्री तने में बिखरे, द्विबीजपत्री जड़ में कम अरीय जाइलम समूह और एकबीजपत्री जड़ में अनेक; पत्ती में ऊपर खंभ ऊतक और नीचे स्पंजी ऊतक।', 'ಛೇದಗಳನ್ನು ಅವುಗಳ ಕಟ್ಟುಗಳಿಂದ ಗುರುತಿಸಲಾಗುತ್ತದೆ: ದ್ವಿದಳ ಕಾಂಡದಲ್ಲಿ ಉಂಗುರ, ಏಕದಳ ಕಾಂಡದಲ್ಲಿ ಚದುರಿದ, ದ್ವಿದಳ ಬೇರಿನಲ್ಲಿ ಕೆಲವು ತ್ರಿಜ್ಯ ಕ್ಸೈಲಮ್ ಗುಂಪುಗಳು, ಏಕದಳ ಬೇರಿನಲ್ಲಿ ಹಲವು; ಎಲೆಯಲ್ಲಿ ಮೇಲೆ ಸ್ತಂಭ ಅಂಗಾಂಶ, ಕೆಳಗೆ ಸ್ಪಂಜು ಅಂಗಾಂಶ.'),
          [Q(W('What is an open vascular bundle?', 'खुला संवहन पूल क्या है?', 'ತೆರೆದ ನಾಳೀಯ ಕಟ್ಟು ಎಂದರೇನು?'), W('One with cambium between xylem and phloem, so it can grow in thickness.', 'जिसमें जाइलम और फ़्लोएम के बीच एधा हो, जिससे मोटाई में वृद्धि हो सके।', 'ಕ್ಸೈಲಮ್ ಮತ್ತು ಫ್ಲೋಯಮ್ ನಡುವೆ ಕ್ಯಾಂಬಿಯಂ ಇರುವುದು; ಹಾಗಾಗಿ ದಪ್ಪದಲ್ಲಿ ಬೆಳೆಯಬಹುದು.')),
           Q(W('What are casparian strips?', 'कैस्पेरियन पट्टियाँ क्या हैं?', 'ಕ್ಯಾಸ್ಪೇರಿಯನ್ ಪಟ್ಟಿಗಳು ಎಂದರೇನು?'), W('Suberin bands on endodermal cell walls that control water entering the stele.', 'अंतस्त्वचा कोशिका भित्तियों पर सुबेरिन की पट्टियाँ जो रंभ में पानी के प्रवेश को नियंत्रित करती हैं।', 'ಅಂತಶ್ಚರ್ಮ ಕೋಶ ಗೋಡೆಗಳ ಮೇಲಿನ ಸುಬೆರಿನ್ ಪಟ್ಟಿಗಳು; ಸ್ಟೀಲ್‌ಗೆ ನೀರಿನ ಪ್ರವೇಶ ನಿಯಂತ್ರಿಸುತ್ತವೆ.')),
           Q(W('Why are there more stomata on the lower surface of a dicot leaf?', 'द्विबीजपत्री पत्ती की निचली सतह पर अधिक रंध्र क्यों होते हैं?', 'ದ್ವಿದಳ ಎಲೆಯ ಕೆಳ ಮೇಲ್ಮೈಯಲ್ಲಿ ಹೆಚ್ಚು ಪತ್ರರಂಧ್ರಗಳು ಏಕೆ?'), W('It is shaded and cooler, so less water is lost.', 'वह छायादार और ठंडी है, इसलिए कम पानी खोता है।', 'ಅದು ನೆರಳಿನಲ್ಲಿದ್ದು ತಂಪು, ಹಾಗಾಗಿ ಕಡಿಮೆ ನೀರು ನಷ್ಟ.')),
           Q(W('Which tissue carries water?', 'कौन सा ऊतक पानी ले जाता है?', 'ಯಾವ ಅಂಗಾಂಶ ನೀರು ಸಾಗಿಸುತ್ತದೆ?'), W('Xylem.', 'जाइलम।', 'ಕ್ಸೈಲಮ್.')),
           Q(W('Name the stain that colours lignified xylem red.', 'वह अभिरंजक बताइए जो लिग्निनयुक्त जाइलम को लाल रंगता है।', 'ಲಿಗ್ನಿನ್‌ಯುಕ್ತ ಕ್ಸೈಲಮನ್ನು ಕೆಂಪಾಗಿಸುವ ಬಣ್ಣ ಹೆಸರಿಸಿ.'), W('Safranin.', 'सैफ़्रानिन।', 'ಸಫ್ರಾನಿನ್.'))])

    study('animal-tissues', 'animal-tissues', puc1,
          ['structural organisation in animals', 'animal tissues', 'epithelium', 'muscle', 'neuron', 'blood', 'connective tissue', 'squamous', 'striated muscle'],
          W('Animal tissues under the microscope', 'सूक्ष्मदर्शी में जंतु ऊतक', 'ಸೂಕ್ಷ್ಮದರ್ಶಕದಲ್ಲಿ ಪ್ರಾಣಿ ಅಂಗಾಂಶಗಳು'),
          W('Study squamous and columnar epithelium, striated and smooth muscle, a neuron and a blood smear.', 'शल्की और स्तंभाकार उपकला, रेखित और चिकनी पेशी, न्यूरॉन और रक्त लेप का अध्ययन करें।', 'ಹುರುಪೆ ಮತ್ತು ಸ್ತಂಭಾಕಾರ ಎಪಿಥೀಲಿಯಂ, ಪಟ್ಟೆ ಮತ್ತು ನಯ ಸ್ನಾಯು, ನರಕೋಶ ಮತ್ತು ರಕ್ತ ಲೇಪ ಅಧ್ಯಯನ ಮಾಡಿ.'),
          W('To study the structure of epithelial, muscular, neural and connective tissues from permanent slides.', 'स्थायी स्लाइडों से उपकला, पेशी, तंत्रिका और संयोजी ऊतकों की संरचना का अध्ययन करना।', 'ಶಾಶ್ವತ ಸ್ಲೈಡ್‌ಗಳಿಂದ ಎಪಿಥೀಲಿಯಲ್, ಸ್ನಾಯು, ನರ ಮತ್ತು ಸಂಯೋಜಕ ಅಂಗಾಂಶಗಳ ರಚನೆ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
          W('A tissue is a group of similar cells doing one job. Epithelia cover and line; muscles contract; neurons conduct impulses; connective tissues, including blood, support and link the body.', 'ऊतक एक कार्य करने वाली समान कोशिकाओं का समूह है। उपकला ढकती और आस्तरित करती है; पेशियाँ संकुचित होती हैं; न्यूरॉन आवेग संचालित करते हैं; संयोजी ऊतक, रक्त सहित, शरीर को सहारा देते और जोड़ते हैं।', 'ಅಂಗಾಂಶ ಒಂದೇ ಕೆಲಸ ಮಾಡುವ ಸಮಾನ ಕೋಶಗಳ ಗುಂಪು. ಎಪಿಥೀಲಿಯಂ ಹೊದಿಸುತ್ತದೆ ಮತ್ತು ಒಳಪದರವಾಗುತ್ತದೆ; ಸ್ನಾಯುಗಳು ಸಂಕುಚಿಸುತ್ತವೆ; ನರಕೋಶಗಳು ಆವೇಗ ಸಾಗಿಸುತ್ತವೆ; ರಕ್ತ ಸೇರಿ ಸಂಯೋಜಕ ಅಂಗಾಂಶಗಳು ದೇಹಕ್ಕೆ ಆಧಾರ ಮತ್ತು ಸಂಪರ್ಕ ನೀಡುತ್ತವೆ.'),
          W('Each tissue’s cell shape fits its work: thin flat cells for exchange, tall cells for absorption, banded fibres for strong voluntary pulls, long axons for conduction and free cells in plasma for transport.', 'प्रत्येक ऊतक की कोशिका आकृति उसके कार्य के अनुरूप है: विनिमय के लिए पतली चपटी कोशिकाएँ, अवशोषण के लिए लंबी कोशिकाएँ, शक्तिशाली ऐच्छिक खिंचाव के लिए पट्टीदार तंतु, संचालन के लिए लंबे ऐक्सॉन और परिवहन के लिए प्लाज़्मा में मुक्त कोशिकाएँ।', 'ಪ್ರತಿ ಅಂಗಾಂಶದ ಕೋಶ ಆಕಾರ ಅದರ ಕೆಲಸಕ್ಕೆ ಹೊಂದುತ್ತದೆ: ವಿನಿಮಯಕ್ಕೆ ತೆಳು ಚಪ್ಪಟೆ ಕೋಶಗಳು, ಹೀರಿಕೆಗೆ ಎತ್ತರದ ಕೋಶಗಳು, ಬಲವಾದ ಐಚ್ಛಿಕ ಎಳೆತಕ್ಕೆ ಪಟ್ಟೆ ತಂತುಗಳು, ವಹನಕ್ಕೆ ಉದ್ದ ಆಕ್ಸಾನ್‌ಗಳು, ಸಾಗಣೆಗೆ ಪ್ಲಾಸ್ಮಾದಲ್ಲಿ ಮುಕ್ತ ಕೋಶಗಳು.'),
          [Q(W('Why do mammalian RBCs have no nucleus?', 'स्तनधारी RBC में केंद्रक क्यों नहीं होता?', 'ಸಸ್ತನಿ RBC ಗಳಲ್ಲಿ ಕೋಶಕೇಂದ್ರ ಏಕಿಲ್ಲ?'), W('To make room for more haemoglobin to carry oxygen.', 'ऑक्सीजन ले जाने के लिए अधिक हीमोग्लोबिन की जगह बनाने हेतु।', 'ಆಮ್ಲಜನಕ ಸಾಗಿಸಲು ಹೆಚ್ಚು ಹಿಮೋಗ್ಲೋಬಿನ್‌ಗೆ ಜಾಗ ಮಾಡಲು.')),
           Q(W('Which muscle is involuntary and unstriated?', 'कौन सी पेशी अनैच्छिक और अरेखित है?', 'ಯಾವ ಸ್ನಾಯು ಅನೈಚ್ಛಿಕ ಮತ್ತು ಪಟ್ಟೆರಹಿತ?'), W('Smooth muscle, as in the walls of the gut.', 'चिकनी पेशी, जैसे आहार नाल की भित्तियों में।', 'ನಯ ಸ್ನಾಯು, ಉದಾ. ಜೀರ್ಣನಾಳದ ಗೋಡೆಗಳಲ್ಲಿ.')),
           Q(W('What does the myelin sheath do?', 'माइलिन आच्छद क्या करता है?', 'ಮೈಲಿನ್ ಕವಚ ಏನು ಮಾಡುತ್ತದೆ?'), W('It insulates the axon and speeds up conduction.', 'यह ऐक्सॉन को विलगित करता है और संचालन तेज़ करता है।', 'ಅದು ಆಕ್ಸಾನನ್ನು ನಿರೋಧಿಸಿ ವಹನ ವೇಗಗೊಳಿಸುತ್ತದೆ.')),
           Q(W('Where is squamous epithelium found?', 'शल्की उपकला कहाँ मिलती है?', 'ಹುರುಪೆ ಎಪಿಥೀಲಿಯಂ ಎಲ್ಲಿ ಕಂಡುಬರುತ್ತದೆ?'), W('In the walls of blood vessels and the air sacs of the lungs.', 'रक्त वाहिकाओं की भित्तियों और फेफड़ों के वायु कोषों में।', 'ರಕ್ತನಾಳಗಳ ಗೋಡೆಗಳು ಮತ್ತು ಶ್ವಾಸಕೋಶದ ವಾಯುಕೋಶಗಳಲ್ಲಿ.')),
           Q(W('What do goblet cells secrete?', 'गॉब्लेट कोशिकाएँ क्या स्रावित करती हैं?', 'ಗಾಬ್ಲೆಟ್ ಕೋಶಗಳು ಏನನ್ನು ಸ್ರವಿಸುತ್ತವೆ?'), W('Mucus.', 'श्लेष्मा।', 'ಲೋಳೆ.'))])

    study('reproduction-slides', 'reproduction', puc2,
          ['human reproduction', 'sexual reproduction in flowering plants', 'testis', 'ovary', 'blastula', 'pollen grain', 'gametogenesis', 'slides'],
          W('Slides of testis, ovary, blastula and pollen grain', 'वृषण, अंडाशय, ब्लास्टुला और परागकण की स्लाइडें', 'ವೃಷಣ, ಅಂಡಾಶಯ, ಬ್ಲಾಸ್ಟುಲಾ ಮತ್ತು ಪರಾಗಕಣದ ಸ್ಲೈಡ್‌ಗಳು'),
          W('Identify the parts of a T.S. of testis and ovary, a blastocyst and a pollen grain.', 'वृषण और अंडाशय की अनुप्रस्थ काट, ब्लास्टोसिस्ट और परागकण के भाग पहचानें।', 'ವೃಷಣ ಮತ್ತು ಅಂಡಾಶಯದ ಅಡ್ಡಛೇದ, ಬ್ಲಾಸ್ಟೋಸಿಸ್ಟ್ ಮತ್ತು ಪರಾಗಕಣದ ಭಾಗಗಳನ್ನು ಗುರುತಿಸಿ.'),
          W('To study prepared slides of the T.S. of testis and ovary, a blastula and a pollen grain.', 'वृषण और अंडाशय की अनुप्रस्थ काट, ब्लास्टुला और परागकण की तैयार स्लाइडों का अध्ययन करना।', 'ವೃಷಣ ಮತ್ತು ಅಂಡಾಶಯದ ಅಡ್ಡಛೇದ, ಬ್ಲಾಸ್ಟುಲಾ ಮತ್ತು ಪರಾಗಕಣದ ಸಿದ್ಧ ಸ್ಲೈಡ್‌ಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
          W('Gametes form by meiosis: sperms in the seminiferous tubules, the ovum in an ovarian follicle. The zygote divides into a hollow blastocyst. In flowering plants the pollen grain is the male gametophyte.', 'युग्मक अर्धसूत्रण से बनते हैं: शुक्राणु शुक्रजनक नलिकाओं में, अंडाणु अंडाशय पुटक में। युग्मनज विभाजित होकर खोखला ब्लास्टोसिस्ट बनाता है। पुष्पी पादपों में परागकण नर युग्मकोद्भिद है।', 'ಯುಗ್ಮಕಗಳು ಅರೆವಿಭಜನೆಯಿಂದ ರೂಪುಗೊಳ್ಳುತ್ತವೆ: ವೀರ್ಯಾಣುಗಳು ಶುಕ್ರಜನಕ ನಳಿಕೆಗಳಲ್ಲಿ, ಅಂಡಾಣು ಅಂಡಾಶಯ ಕೋಶಕದಲ್ಲಿ. ಯುಗ್ಮಜ ವಿಭಜಿಸಿ ಟೊಳ್ಳು ಬ್ಲಾಸ್ಟೋಸಿಸ್ಟ್ ಆಗುತ್ತದೆ. ಹೂಬಿಡುವ ಸಸ್ಯಗಳಲ್ಲಿ ಪರಾಗಕಣ ಗಂಡು ಯುಗ್ಮಕೋದ್ಭಿದ.'),
          W('The slides show sperm formation in seminiferous tubules, follicles maturing in the ovary, the inner cell mass of the blastocyst and the two cells of a pollen grain.', 'स्लाइडें शुक्रजनक नलिकाओं में शुक्राणु निर्माण, अंडाशय में परिपक्व होते पुटक, ब्लास्टोसिस्ट का आंतरिक कोशिका समूह और परागकण की दो कोशिकाएँ दिखाती हैं।', 'ಸ್ಲೈಡ್‌ಗಳು ಶುಕ್ರಜನಕ ನಳಿಕೆಗಳಲ್ಲಿ ವೀರ್ಯ ರಚನೆ, ಅಂಡಾಶಯದಲ್ಲಿ ಪಕ್ವವಾಗುವ ಕೋಶಕಗಳು, ಬ್ಲಾಸ್ಟೋಸಿಸ್ಟ್‌ನ ಒಳ ಕೋಶ ರಾಶಿ ಮತ್ತು ಪರಾಗಕಣದ ಎರಡು ಕೋಶಗಳನ್ನು ತೋರಿಸುತ್ತವೆ.'),
          [Q(W('What do Leydig cells secrete?', 'लेडिग कोशिकाएँ क्या स्रावित करती हैं?', 'ಲೇಡಿಗ್ ಕೋಶಗಳು ಏನನ್ನು ಸ್ರವಿಸುತ್ತವೆ?'), W('Androgens such as testosterone.', 'टेस्टोस्टेरॉन जैसे ऐंड्रोजन।', 'ಟೆಸ್ಟೋಸ್ಟೆರೋನ್‌ನಂತಹ ಆಂಡ್ರೋಜನ್‌ಗಳು.')),
           Q(W('What does the corpus luteum secrete?', 'पीत पिंड क्या स्रावित करता है?', 'ಕಾರ್ಪಸ್ ಲೂಟಿಯಂ ಏನನ್ನು ಸ್ರವಿಸುತ್ತದೆ?'), W('Progesterone, which maintains the uterine lining.', 'प्रोजेस्टेरॉन, जो गर्भाशय की भित्ति बनाए रखता है।', 'ಪ್ರೊಜೆಸ್ಟೆರೋನ್, ಗರ್ಭಾಶಯದ ಒಳಪದರ ಕಾಪಾಡುತ್ತದೆ.')),
           Q(W('Which part of the blastocyst becomes the embryo?', 'ब्लास्टोसिस्ट का कौन सा भाग भ्रूण बनता है?', 'ಬ್ಲಾಸ್ಟೋಸಿಸ್ಟ್‌ನ ಯಾವ ಭಾಗ ಭ್ರೂಣವಾಗುತ್ತದೆ?'), W('The inner cell mass.', 'आंतरिक कोशिका समूह।', 'ಒಳ ಕೋಶ ರಾಶಿ.')),
           Q(W('What is the exine of pollen made of?', 'पराग का बाह्यचोल किससे बना है?', 'ಪರಾಗದ ಹೊರಪದರ ಯಾವುದರಿಂದಾಗಿದೆ?'), W('Sporopollenin, one of the most resistant organic materials.', 'स्पोरोपोलेनिन, सबसे प्रतिरोधी कार्बनिक पदार्थों में से एक।', 'ಸ್ಪೋರೋಪೊಲೆನಿನ್, ಅತ್ಯಂತ ನಿರೋಧಕ ಸಾವಯವ ವಸ್ತುಗಳಲ್ಲಿ ಒಂದು.')),
           Q(W('What does the generative cell of pollen form?', 'पराग की जनन कोशिका क्या बनाती है?', 'ಪರಾಗದ ಜನನ ಕೋಶ ಏನನ್ನು ರೂಪಿಸುತ್ತದೆ?'), W('Two male gametes.', 'दो नर युग्मक।', 'ಎರಡು ಗಂಡು ಯುಗ್ಮಕಗಳು.'))])

    study('disease-organisms', 'pathogens', puc2,
          ['human health and disease', 'pathogens', 'malaria', 'amoebiasis', 'ascariasis', 'ringworm', 'plasmodium', 'entamoeba', 'disease-causing organisms'],
          W('Disease-causing organisms', 'रोग पैदा करने वाले जीव', 'ರೋಗಕಾರಕ ಜೀವಿಗಳು'),
          W('Study Entamoeba, Plasmodium, Ascaris and Trichophyton, and the diseases they cause.', 'एंटअमीबा, प्लाज़्मोडियम, ऐस्केरिस और ट्राइकोफ़ाइटॉन और उनसे होने वाले रोगों का अध्ययन करें।', 'ಎಂಟಮೀಬಾ, ಪ್ಲಾಸ್ಮೋಡಿಯಂ, ಆಸ್ಕರಿಸ್ ಮತ್ತು ಟ್ರೈಕೋಫೈಟಾನ್ ಹಾಗೂ ಅವು ಉಂಟುಮಾಡುವ ರೋಗಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ.'),
          W('To identify common disease-causing organisms from slides and specimens and to learn the symptoms and spread of the diseases they cause.', 'स्लाइडों और नमूनों से सामान्य रोगजनक जीवों की पहचान करना और उनसे होने वाले रोगों के लक्षण और प्रसार जानना।', 'ಸ್ಲೈಡ್ ಮತ್ತು ಮಾದರಿಗಳಿಂದ ಸಾಮಾನ್ಯ ರೋಗಕಾರಕ ಜೀವಿಗಳನ್ನು ಗುರುತಿಸಿ ಅವು ಉಂಟುಮಾಡುವ ರೋಗಗಳ ಲಕ್ಷಣ ಮತ್ತು ಹರಡುವಿಕೆ ತಿಳಿಯುವುದು.'),
          W('Pathogens include protozoa, worms and fungi. Knowing how each spreads (food and water, mosquitoes, soil, contact) shows how to prevent it.', 'रोगजनकों में प्रोटोज़ोआ, कृमि और कवक शामिल हैं। प्रत्येक कैसे फैलता है (भोजन और पानी, मच्छर, मिट्टी, संपर्क) जानने से बचाव का तरीका पता चलता है।', 'ರೋಗಕಾರಕಗಳಲ್ಲಿ ಪ್ರೋಟೋಜೋವಾ, ಹುಳುಗಳು ಮತ್ತು ಶಿಲೀಂಧ್ರಗಳಿವೆ. ಪ್ರತಿಯೊಂದು ಹೇಗೆ ಹರಡುತ್ತದೆ (ಆಹಾರ ಮತ್ತು ನೀರು, ಸೊಳ್ಳೆ, ಮಣ್ಣು, ಸಂಪರ್ಕ) ಎಂದು ತಿಳಿದರೆ ತಡೆಯುವ ದಾರಿ ತಿಳಿಯುತ್ತದೆ.'),
          W('Entamoeba causes amoebic dysentery, Plasmodium malaria, Ascaris ascariasis and Trichophyton ringworm; clean water, mosquito control and hygiene prevent them.', 'एंटअमीबा अमीबी पेचिश, प्लाज़्मोडियम मलेरिया, ऐस्केरिस ऐस्केरिएसिस और ट्राइकोफ़ाइटॉन दाद करता है; स्वच्छ जल, मच्छर नियंत्रण और स्वच्छता इन्हें रोकते हैं।', 'ಎಂಟಮೀಬಾ ಅಮೀಬಿಕ್ ಆಮಶಂಕೆ, ಪ್ಲಾಸ್ಮೋಡಿಯಂ ಮಲೇರಿಯಾ, ಆಸ್ಕರಿಸ್ ಆಸ್ಕರಿಯಾಸಿಸ್ ಮತ್ತು ಟ್ರೈಕೋಫೈಟಾನ್ ಹುಳುಕಡ್ಡಿ ಉಂಟುಮಾಡುತ್ತವೆ; ಶುದ್ಧ ನೀರು, ಸೊಳ್ಳೆ ನಿಯಂತ್ರಣ ಮತ್ತು ನೈರ್ಮಲ್ಯ ತಡೆಯುತ್ತವೆ.'),
          [Q(W('Which mosquito spreads malaria?', 'कौन सा मच्छर मलेरिया फैलाता है?', 'ಯಾವ ಸೊಳ್ಳೆ ಮಲೇರಿಯಾ ಹರಡುತ್ತದೆ?'), W('The female Anopheles.', 'मादा ऐनोफ़िलीज़।', 'ಹೆಣ್ಣು ಅನಾಫಿಲಿಸ್.')),
           Q(W('What causes the chills and fever of malaria?', 'मलेरिया में ठंड और ज्वर किससे होता है?', 'ಮಲೇರಿಯಾದ ಚಳಿ ಮತ್ತು ಜ್ವರಕ್ಕೆ ಕಾರಣವೇನು?'), W('Haemozoin, a toxin released when infected red blood cells burst.', 'हीमोज़ोइन, संक्रमित लाल रक्त कोशिकाओं के फटने पर निकलने वाला विष।', 'ಹಿಮೋಜೋಯಿನ್, ಸೋಂಕಿತ ಕೆಂಪು ರಕ್ತಕಣಗಳು ಒಡೆದಾಗ ಬಿಡುಗಡೆಯಾಗುವ ವಿಷ.')),
           Q(W('How does Ascaris spread?', 'ऐस्केरिस कैसे फैलता है?', 'ಆಸ್ಕರಿಸ್ ಹೇಗೆ ಹರಡುತ್ತದೆ?'), W('Its eggs pass out in faeces and contaminate soil, water and vegetables.', 'इसके अंडे मल के साथ निकलकर मिट्टी, पानी और सब्ज़ियों को दूषित करते हैं।', 'ಅದರ ಮೊಟ್ಟೆಗಳು ಮಲದೊಂದಿಗೆ ಹೊರಬಂದು ಮಣ್ಣು, ನೀರು ಮತ್ತು ತರಕಾರಿಗಳನ್ನು ಕಲುಷಿತಗೊಳಿಸುತ್ತವೆ.')),
           Q(W('Is ringworm caused by a worm?', 'क्या दाद कृमि से होता है?', 'ಹುಳುಕಡ್ಡಿ ಹುಳುವಿನಿಂದ ಆಗುತ್ತದೆಯೇ?'), W('No: by fungi such as Trichophyton, Microsporum and Epidermophyton.', 'नहीं: ट्राइकोफ़ाइटॉन, माइक्रोस्पोरम और एपिडर्मोफ़ाइटॉन जैसे कवकों से।', 'ಇಲ್ಲ: ಟ್ರೈಕೋಫೈಟಾನ್, ಮೈಕ್ರೋಸ್ಪೋರಮ್ ಮತ್ತು ಎಪಿಡರ್ಮೋಫೈಟಾನ್‌ನಂತಹ ಶಿಲೀಂಧ್ರಗಳಿಂದ.')),
           Q(W('What sign of amoebiasis is seen in the stool?', 'मल में अमीबता का कौन सा लक्षण दिखता है?', 'ಮಲದಲ್ಲಿ ಅಮೀಬಿಯಾಸಿಸ್‌ನ ಯಾವ ಲಕ್ಷಣ ಕಾಣುತ್ತದೆ?'), W('Mucus and blood.', 'श्लेष्मा और रक्त।', 'ಲೋಳೆ ಮತ್ತು ರಕ್ತ.'))])

    study('homology-adaptations', 'adaptations', puc2,
          ['evolution', 'homologous organs', 'adaptation', 'xerophyte', 'hydrophyte', 'organisms and populations', 'divergent evolution', 'opuntia'],
          W('Homologous organs and plant adaptations', 'समजात अंग और पादप अनुकूलन', 'ಸಮರೂಪಿ ಅಂಗಗಳು ಮತ್ತು ಸಸ್ಯ ಹೊಂದಾಣಿಕೆಗಳು'),
          W('Compare the forelimbs of a human, a whale and a bat, and the adaptations of Opuntia and water hyacinth.', 'मनुष्य, व्हेल और चमगादड़ के अग्रपादों तथा नागफनी और जलकुंभी के अनुकूलनों की तुलना करें।', 'ಮನುಷ್ಯ, ತಿಮಿಂಗಿಲ ಮತ್ತು ಬಾವಲಿಯ ಮುಂಗಾಲುಗಳು ಹಾಗೂ ಪಾಪಾಸುಕಳ್ಳಿ ಮತ್ತು ಜಲಕುಂಭಿಯ ಹೊಂದಾಣಿಕೆಗಳನ್ನು ಹೋಲಿಸಿ.'),
          W('To study homologous organs as evidence of evolution and the adaptations of plants to dry and aquatic habitats.', 'विकास के प्रमाण के रूप में समजात अंगों का और शुष्क तथा जलीय आवासों के लिए पादपों के अनुकूलनों का अध्ययन करना।', 'ವಿಕಾಸದ ಸಾಕ್ಷಿಯಾಗಿ ಸಮರೂಪಿ ಅಂಗಗಳು ಮತ್ತು ಒಣ ಹಾಗೂ ಜಲ ವಾಸಸ್ಥಾನಗಳಿಗೆ ಸಸ್ಯಗಳ ಹೊಂದಾಣಿಕೆಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
          W('Homologous organs share one plan of bones but serve different uses (divergent evolution from a common ancestor). Adaptations are features that suit an organism to its habitat.', 'समजात अंगों में अस्थियों की एक ही योजना होती है पर उपयोग भिन्न होते हैं (एक पूर्वज से अपसारी विकास)। अनुकूलन वे लक्षण हैं जो जीव को उसके आवास के अनुकूल बनाते हैं।', 'ಸಮರೂಪಿ ಅಂಗಗಳಲ್ಲಿ ಮೂಳೆಗಳ ಒಂದೇ ವಿನ್ಯಾಸ, ಆದರೆ ಬೇರೆ ಬಳಕೆ (ಸಾಮಾನ್ಯ ಪೂರ್ವಜನಿಂದ ಅಪಸರಣ ವಿಕಾಸ). ಹೊಂದಾಣಿಕೆಗಳು ಜೀವಿಯನ್ನು ಅದರ ವಾಸಸ್ಥಾನಕ್ಕೆ ಹೊಂದಿಸುವ ಲಕ್ಷಣಗಳು.'),
          W('The three forelimbs have the same bones for grasping, swimming and flying, pointing to a common ancestor; Opuntia saves water and water hyacinth floats on air-filled petioles.', 'तीनों अग्रपादों में पकड़ने, तैरने और उड़ने के लिए समान अस्थियाँ हैं, जो एक पूर्वज की ओर संकेत करती हैं; नागफनी पानी बचाती है और जलकुंभी वायु भरे पर्णवृंतों पर तैरती है।', 'ಮೂರು ಮುಂಗಾಲುಗಳಲ್ಲಿ ಹಿಡಿಯಲು, ಈಜಲು ಮತ್ತು ಹಾರಲು ಒಂದೇ ಮೂಳೆಗಳಿವೆ, ಸಾಮಾನ್ಯ ಪೂರ್ವಜನನ್ನು ಸೂಚಿಸುತ್ತವೆ; ಪಾಪಾಸುಕಳ್ಳಿ ನೀರು ಉಳಿಸುತ್ತದೆ, ಜಲಕುಂಭಿ ಗಾಳಿ ತುಂಬಿದ ತೊಟ್ಟುಗಳ ಮೇಲೆ ತೇಲುತ್ತದೆ.'),
          [Q(W('Give an example of analogous organs.', 'समरूप अंगों का एक उदाहरण दीजिए।', 'ಸಮಕಾರ್ಯ ಅಂಗಗಳ ಉದಾಹರಣೆ ಕೊಡಿ.'), W('The wings of a butterfly and a bird: same use, different structure.', 'तितली और पक्षी के पंख: उपयोग समान, संरचना भिन्न।', 'ಚಿಟ್ಟೆ ಮತ್ತು ಹಕ್ಕಿಯ ರೆಕ್ಕೆಗಳು: ಒಂದೇ ಬಳಕೆ, ಬೇರೆ ರಚನೆ.')),
           Q(W('What do homologous organs show?', 'समजात अंग क्या दर्शाते हैं?', 'ಸಮರೂಪಿ ಅಂಗಗಳು ಏನನ್ನು ತೋರಿಸುತ್ತವೆ?'), W('Divergent evolution from a common ancestor.', 'एक सामान्य पूर्वज से अपसारी विकास।', 'ಸಾಮಾನ್ಯ ಪೂರ್ವಜನಿಂದ ಅಪಸರಣ ವಿಕಾಸ.')),
           Q(W('Why are the leaves of Opuntia reduced to spines?', 'नागफनी की पत्तियाँ काँटों में क्यों बदल गई हैं?', 'ಪಾಪಾಸುಕಳ್ಳಿಯ ಎಲೆಗಳು ಮುಳ್ಳುಗಳಾಗಿರುವುದೇಕೆ?'), W('To reduce water loss and to protect the plant from animals.', 'जल हानि घटाने और पौधे को जंतुओं से बचाने के लिए।', 'ನೀರಿನ ನಷ್ಟ ತಗ್ಗಿಸಲು ಮತ್ತು ಪ್ರಾಣಿಗಳಿಂದ ರಕ್ಷಿಸಲು.')),
           Q(W('How does Opuntia photosynthesise?', 'नागफनी प्रकाश-संश्लेषण कैसे करती है?', 'ಪಾಪಾಸುಕಳ್ಳಿ ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆ ಹೇಗೆ ಮಾಡುತ್ತದೆ?'), W('With its flat green stem (phylloclade), by the CAM pathway.', 'अपने चपटे हरे तने (पर्णाभ स्तंभ) से, CAM पथ द्वारा।', 'ಚಪ್ಪಟೆ ಹಸಿರು ಕಾಂಡದಿಂದ (ಫಿಲೋಕ್ಲೇಡ್), CAM ಮಾರ್ಗದಿಂದ.')),
           Q(W('What tissue fills the swollen petiole of water hyacinth?', 'जलकुंभी के फूले पर्णवृंत में कौन सा ऊतक भरा होता है?', 'ಜಲಕುಂಭಿಯ ಉಬ್ಬಿದ ತೊಟ್ಟಿನಲ್ಲಿ ಯಾವ ಅಂಗಾಂಶ?'), W('Aerenchyma: parenchyma with large air spaces.', 'वायूतक: बड़े वायु अवकाशों वाला मृदूतक।', 'ಏರೆಂಕೈಮಾ: ದೊಡ್ಡ ಗಾಳಿ ಸ್ಥಳಗಳಿರುವ ಪ್ಯಾರೆಂಕೈಮಾ.'))],
          apparatus=[SPEC, W('Charts of forelimb bones', 'अग्रपाद अस्थियों के चार्ट', 'ಮುಂಗಾಲು ಮೂಳೆಗಳ ಚಾರ್ಟ್‌ಗಳು'), W('Potted Opuntia and water hyacinth', 'गमले में नागफनी और जलकुंभी', 'ಕುಂಡದಲ್ಲಿ ಪಾಪಾಸುಕಳ್ಳಿ ಮತ್ತು ಜಲಕುಂಭಿ'), RECORD])

    # ------------------------------------------------------------ spot kits
    lab(id='urine-analysis', bench='spot-test', setup={'kit': 'urine'}, **puc1,
        keywords=['excretory products and their elimination', 'urine', 'glucose in urine', 'albumin', 'bile salts', 'diabetes', 'urine analysis'],
        title=W('Tests for sugar, albumin and bile in urine', 'मूत्र में शर्करा, एल्ब्यूमिन और पित्त के परीक्षण', 'ಮೂತ್ರದಲ್ಲಿ ಸಕ್ಕರೆ, ಆಲ್ಬುಮಿನ್ ಮತ್ತು ಪಿತ್ತದ ಪರೀಕ್ಷೆಗಳು'),
        summary=W("Test four urine samples with Benedict's, the heat-coagulation test, Hay's and Gmelin's tests, and say what each result means.", 'चार मूत्र नमूनों का बेनेडिक्ट, ताप-स्कंदन, हे और ग्मेलिन परीक्षणों से परीक्षण करें और हर परिणाम का अर्थ बताएँ।', 'ನಾಲ್ಕು ಮೂತ್ರ ಮಾದರಿಗಳನ್ನು ಬೆನೆಡಿಕ್ಟ್, ಉಷ್ಣ-ಹೆಪ್ಪು, ಹೇ ಮತ್ತು ಗ್ಮೆಲಿನ್ ಪರೀಕ್ಷೆಗಳಿಂದ ಪರೀಕ್ಷಿಸಿ ಪ್ರತಿ ಫಲಿತಾಂಶದ ಅರ್ಥ ತಿಳಿಸಿ.'),
        aim=W('To detect the presence of glucose, albumin and bile salts and pigments in urine samples.', 'मूत्र नमूनों में ग्लूकोज़, एल्ब्यूमिन और पित्त लवण तथा वर्णकों की उपस्थिति का पता लगाना।', 'ಮೂತ್ರ ಮಾದರಿಗಳಲ್ಲಿ ಗ್ಲೂಕೋಸ್, ಆಲ್ಬುಮಿನ್ ಮತ್ತು ಪಿತ್ತ ಲವಣ ಹಾಗೂ ವರ್ಣಕಗಳ ಇರುವಿಕೆ ಪತ್ತೆಹಚ್ಚುವುದು.'),
        principle=W("Normal urine has no glucose, protein or bile. Glucose reduces Benedict's reagent to red Cu₂O (diabetes mellitus); albumin coagulates on heating (kidney disease); bile salts lower surface tension so sulphur powder sinks, and bile pigments give coloured rings with nitric acid (jaundice).", 'सामान्य मूत्र में ग्लूकोज़, प्रोटीन या पित्त नहीं होता। ग्लूकोज़ बेनेडिक्ट अभिकर्मक को लाल Cu₂O में अपचयित करता है (मधुमेह); एल्ब्यूमिन गर्म करने पर स्कंदित होता है (वृक्क रोग); पित्त लवण पृष्ठ तनाव घटाते हैं जिससे गंधक चूर्ण डूब जाता है, और पित्त वर्णक नाइट्रिक अम्ल से रंगीन वलय देते हैं (पीलिया)।', 'ಸಾಮಾನ್ಯ ಮೂತ್ರದಲ್ಲಿ ಗ್ಲೂಕೋಸ್, ಪ್ರೋಟೀನ್ ಅಥವಾ ಪಿತ್ತ ಇರುವುದಿಲ್ಲ. ಗ್ಲೂಕೋಸ್ ಬೆನೆಡಿಕ್ಟ್ ಕಾರಕವನ್ನು ಕೆಂಪು Cu₂O ಗೆ ಅಪಕರ್ಷಿಸುತ್ತದೆ (ಮಧುಮೇಹ); ಆಲ್ಬುಮಿನ್ ಬಿಸಿಮಾಡಿದಾಗ ಹೆಪ್ಪುಗಟ್ಟುತ್ತದೆ (ಮೂತ್ರಪಿಂಡ ರೋಗ); ಪಿತ್ತ ಲವಣಗಳು ಮೇಲ್ಮೈ ಸೆಳೆತ ತಗ್ಗಿಸಿ ಗಂಧಕ ಪುಡಿ ಮುಳುಗುತ್ತದೆ, ಪಿತ್ತ ವರ್ಣಕಗಳು ನೈಟ್ರಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಬಣ್ಣದ ಉಂಗುರ ನೀಡುತ್ತವೆ (ಕಾಮಾಲೆ).'),
        apparatus=[W('Test tubes, holder and burner', 'परखनलियाँ, होल्डर और बर्नर', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು, ಹಿಡಿಕೆ ಮತ್ತು ಬರ್ನರ್'), W('Urine samples 1–4', 'मूत्र नमूने 1–4', 'ಮೂತ್ರ ಮಾದರಿಗಳು 1–4'), W("Benedict's reagent, acetic acid, sulphur powder, conc. HNO₃", 'बेनेडिक्ट अभिकर्मक, ऐसीटिक अम्ल, गंधक चूर्ण, सांद्र HNO₃', 'ಬೆನೆಡಿಕ್ಟ್ ಕಾರಕ, ಅಸಿಟಿಕ್ ಆಮ್ಲ, ಗಂಧಕ ಪುಡಿ, ಸಾಂದ್ರ HNO₃')],
        steps=[W("Glucose: boil 0.5 mL urine with 5 mL Benedict's reagent and watch for a red precipitate.", 'ग्लूकोज़: 0.5 mL मूत्र को 5 mL बेनेडिक्ट अभिकर्मक के साथ उबालें और लाल अवक्षेप देखें।', 'ಗ್ಲೂಕೋಸ್: 0.5 mL ಮೂತ್ರವನ್ನು 5 mL ಬೆನೆಡಿಕ್ಟ್ ಕಾರಕದೊಂದಿಗೆ ಕುದಿಸಿ ಕೆಂಪು ಅವಕ್ಷೇಪ ನೋಡಿ.'),
               W('Albumin: heat the upper part of a tube of urine and add a few drops of acetic acid.', 'एल्ब्यूमिन: मूत्र की परखनली का ऊपरी भाग गर्म करें और कुछ बूँद ऐसीटिक अम्ल डालें।', 'ಆಲ್ಬುಮಿನ್: ಮೂತ್ರದ ನಳಿಕೆಯ ಮೇಲ್ಭಾಗ ಬಿಸಿಮಾಡಿ ಕೆಲವು ಹನಿ ಅಸಿಟಿಕ್ ಆಮ್ಲ ಸೇರಿಸಿ.'),
               W('Bile salts: sprinkle sulphur powder on the urine surface.', 'पित्त लवण: मूत्र की सतह पर गंधक चूर्ण छिड़कें।', 'ಪಿತ್ತ ಲವಣ: ಮೂತ್ರದ ಮೇಲ್ಮೈಗೆ ಗಂಧಕ ಪುಡಿ ಉದುರಿಸಿ.'),
               W('Bile pigments: layer urine over conc. HNO₃ and look at the junction.', 'पित्त वर्णक: सांद्र HNO₃ पर मूत्र की परत बनाएँ और संधि पर देखें।', 'ಪಿತ್ತ ವರ್ಣಕ: ಸಾಂದ್ರ HNO₃ ಮೇಲೆ ಮೂತ್ರದ ಪದರ ಮಾಡಿ ಸಂಧಿಯಲ್ಲಿ ನೋಡಿ.'),
               W('Record each result and the condition it points to.', 'हर परिणाम और उससे सूचित स्थिति लिखें।', 'ಪ್ರತಿ ಫಲಿತಾಂಶ ಮತ್ತು ಅದು ಸೂಚಿಸುವ ಸ್ಥಿತಿ ದಾಖಲಿಸಿ.')],
        precautions=[W('Wear gloves and wash hands after handling urine.', 'मूत्र छूने के बाद दस्ताने पहनें और हाथ धोएँ।', 'ಮೂತ್ರ ಮುಟ್ಟಿದ ನಂತರ ಕೈಗವಸು ಧರಿಸಿ ಕೈ ತೊಳೆಯಿರಿ.'), W('Use fresh samples in clean tubes.', 'साफ़ परखनलियों में ताज़े नमूने लें।', 'ಸ್ವಚ್ಛ ನಳಿಕೆಗಳಲ್ಲಿ ತಾಜಾ ಮಾದರಿ ಬಳಸಿ.'), W('Point the heated tube away from everyone.', 'गर्म परखनली को सबसे दूर रखें।', 'ಬಿಸಿ ನಳಿಕೆಯನ್ನು ಎಲ್ಲರಿಂದ ದೂರ ಇಡಿ.')],
        conclusion=W('Sample 1 is normal; sample 2 has glucose (diabetes mellitus), sample 3 albumin (kidney disease), and sample 4 bile salts and pigments (jaundice).', 'नमूना 1 सामान्य है; नमूना 2 में ग्लूकोज़ (मधुमेह), नमूना 3 में एल्ब्यूमिन (वृक्क रोग), और नमूना 4 में पित्त लवण तथा वर्णक (पीलिया) हैं।', 'ಮಾದರಿ 1 ಸಾಮಾನ್ಯ; ಮಾದರಿ 2 ರಲ್ಲಿ ಗ್ಲೂಕೋಸ್ (ಮಧುಮೇಹ), ಮಾದರಿ 3 ರಲ್ಲಿ ಆಲ್ಬುಮಿನ್ (ಮೂತ್ರಪಿಂಡ ರೋಗ), ಮಾದರಿ 4 ರಲ್ಲಿ ಪಿತ್ತ ಲವಣ ಮತ್ತು ವರ್ಣಕಗಳು (ಕಾಮಾಲೆ).'),
        viva=[Q(W('What is glycosuria?', 'ग्लाइकोसूरिया क्या है?', 'ಗ್ಲೈಕೋಸೂರಿಯಾ ಎಂದರೇನು?'), W('Glucose in the urine.', 'मूत्र में ग्लूकोज़।', 'ಮೂತ್ರದಲ್ಲಿ ಗ್ಲೂಕೋಸ್.')),
              Q(W('Which hormone is lacking in diabetes mellitus?', 'मधुमेह में कौन सा हॉर्मोन कम होता है?', 'ಮಧುಮೇಹದಲ್ಲಿ ಯಾವ ಹಾರ್ಮೋನ್ ಕೊರತೆ?'), W('Insulin.', 'इंसुलिन।', 'ಇನ್ಸುಲಿನ್.')),
              Q(W('Why is acetic acid added in the albumin test?', 'एल्ब्यूमिन परीक्षण में ऐसीटिक अम्ल क्यों डालते हैं?', 'ಆಲ್ಬುಮಿನ್ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಅಸಿಟಿಕ್ ಆಮ್ಲ ಏಕೆ?'), W('Phosphates also cloud on heating but dissolve in acid; albumin does not.', 'फ़ॉस्फ़ेट भी गर्म करने पर धुंधले होते हैं पर अम्ल में घुल जाते हैं; एल्ब्यूमिन नहीं।', 'ಫಾಸ್ಫೇಟ್‌ಗಳೂ ಬಿಸಿಯಲ್ಲಿ ಮಸುಕಾಗುತ್ತವೆ ಆದರೆ ಆಮ್ಲದಲ್ಲಿ ಕರಗುತ್ತವೆ; ಆಲ್ಬುಮಿನ್ ಕರಗುವುದಿಲ್ಲ.')),
              Q(W('Why does sulphur powder sink when bile salts are present?', 'पित्त लवण होने पर गंधक चूर्ण क्यों डूबता है?', 'ಪಿತ್ತ ಲವಣ ಇದ್ದಾಗ ಗಂಧಕ ಪುಡಿ ಏಕೆ ಮುಳುಗುತ್ತದೆ?'), W('Bile salts lower the surface tension of urine.', 'पित्त लवण मूत्र का पृष्ठ तनाव घटाते हैं।', 'ಪಿತ್ತ ಲವಣಗಳು ಮೂತ್ರದ ಮೇಲ್ಮೈ ಸೆಳೆತ ತಗ್ಗಿಸುತ್ತವೆ.')),
              Q(W('What gives normal urine its yellow colour?', 'सामान्य मूत्र का पीला रंग किससे होता है?', 'ಸಾಮಾನ್ಯ ಮೂತ್ರದ ಹಳದಿ ಬಣ್ಣಕ್ಕೆ ಕಾರಣ?'), W('Urochrome, a pigment from the breakdown of haemoglobin.', 'यूरोक्रोम, हीमोग्लोबिन के विघटन से बना वर्णक।', 'ಯೂರೋಕ್ರೋಮ್, ಹಿಮೋಗ್ಲೋಬಿನ್ ವಿಘಟನೆಯ ವರ್ಣಕ.'))])

    lab(id='water-soil-analysis', bench='spot-test', setup={'kit': 'water'}, **puc2,
        keywords=['ecosystem', 'organisms and populations', 'water quality', 'soil', 'ph', 'turbidity', 'hardness', 'pollution', 'environmental issues'],
        title=W('pH and clarity of water and soil from different sites', 'विभिन्न स्थानों के जल और मिट्टी का pH और स्वच्छता', 'ಬೇರೆ ಬೇರೆ ಸ್ಥಳಗಳ ನೀರು ಮತ್ತು ಮಣ್ಣಿನ pH ಮತ್ತು ಸ್ಪಷ್ಟತೆ'),
        summary=W('Test tap, pond and borewell water and garden and roadside soil for pH, clarity, hardness and chloride.', 'नल, तालाब और बोरवेल के जल तथा बगीचे और सड़क किनारे की मिट्टी का pH, स्वच्छता, कठोरता और क्लोराइड के लिए परीक्षण करें।', 'ನಲ್ಲಿ, ಕೊಳ ಮತ್ತು ಕೊಳವೆ ಬಾವಿ ನೀರು ಹಾಗೂ ತೋಟ ಮತ್ತು ರಸ್ತೆಬದಿ ಮಣ್ಣನ್ನು pH, ಸ್ಪಷ್ಟತೆ, ಗಡಸುತನ ಮತ್ತು ಕ್ಲೋರೈಡ್‌ಗೆ ಪರೀಕ್ಷಿಸಿ.'),
        aim=W('To study the pH and clarity of water samples and soil from at least two different sites.', 'कम से कम दो विभिन्न स्थानों के जल नमूनों और मिट्टी का pH और स्वच्छता अध्ययन करना।', 'ಕನಿಷ್ಠ ಎರಡು ಬೇರೆ ಸ್ಥಳಗಳ ನೀರಿನ ಮಾದರಿ ಮತ್ತು ಮಣ್ಣಿನ pH ಹಾಗೂ ಸ್ಪಷ್ಟತೆ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Universal indicator shows pH by colour (red acidic, green neutral, blue alkaline). Suspended particles make water turbid. Hard water (Ca²⁺, Mg²⁺) forms scum with soap. The pH and clarity of a site decide which organisms can live there.', 'सार्वत्रिक सूचक रंग से pH दिखाता है (लाल अम्लीय, हरा उदासीन, नीला क्षारीय)। निलंबित कण जल को गंदला बनाते हैं। कठोर जल (Ca²⁺, Mg²⁺) साबुन से मैल बनाता है। किसी स्थान का pH और स्वच्छता तय करते हैं कि वहाँ कौन से जीव रह सकते हैं।', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಬಣ್ಣದಿಂದ pH ತೋರಿಸುತ್ತದೆ (ಕೆಂಪು ಆಮ್ಲೀಯ, ಹಸಿರು ತಟಸ್ಥ, ನೀಲಿ ಕ್ಷಾರೀಯ). ತೇಲುವ ಕಣಗಳು ನೀರನ್ನು ಮಸುಕಾಗಿಸುತ್ತವೆ. ಗಡಸು ನೀರು (Ca²⁺, Mg²⁺) ಸಾಬೂನಿನೊಂದಿಗೆ ಕಸ ರೂಪಿಸುತ್ತದೆ. ಸ್ಥಳದ pH ಮತ್ತು ಸ್ಪಷ್ಟತೆ ಅಲ್ಲಿ ಯಾವ ಜೀವಿಗಳು ಬದುಕಬಹುದು ಎಂದು ನಿರ್ಧರಿಸುತ್ತವೆ.'),
        apparatus=[W('Test tubes and beakers', 'परखनलियाँ और बीकर', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು ಮತ್ತು ಬೀಕರ್‌ಗಳು'), W('Universal indicator and colour chart', 'सार्वत्रिक सूचक और रंग चार्ट', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಮತ್ತು ಬಣ್ಣ ಚಾರ್ಟ್'), W('Water and soil samples', 'जल और मिट्टी के नमूने', 'ನೀರು ಮತ್ತು ಮಣ್ಣಿನ ಮಾದರಿಗಳು'), W('Soap solution, AgNO₃, white card with a black cross', 'साबुन विलयन, AgNO₃, काले क्रॉस वाला सफ़ेद कार्ड', 'ಸಾಬೂನು ದ್ರಾವಣ, AgNO₃, ಕಪ್ಪು ಅಡ್ಡಗುರುತಿನ ಬಿಳಿ ಕಾರ್ಡ್')],
        steps=[W('Shake each soil sample with distilled water and let it settle; use the liquid above.', 'प्रत्येक मिट्टी नमूने को आसुत जल के साथ हिलाएँ और बैठने दें; ऊपर का द्रव लें।', 'ಪ್ರತಿ ಮಣ್ಣಿನ ಮಾದರಿಯನ್ನು ಬಟ್ಟಿ ನೀರಿನೊಂದಿಗೆ ಅಲುಗಾಡಿಸಿ ತಳ ಕೂರಲು ಬಿಡಿ; ಮೇಲಿನ ದ್ರವ ಬಳಸಿ.'),
               W('Add universal indicator and match the colour with the chart.', 'सार्वत्रिक सूचक डालें और रंग का चार्ट से मिलान करें।', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಸೇರಿಸಿ ಬಣ್ಣವನ್ನು ಚಾರ್ಟ್‌ನೊಂದಿಗೆ ಹೊಂದಿಸಿ.'),
               W('Look through each sample at a black cross to judge its clarity.', 'स्वच्छता आँकने के लिए प्रत्येक नमूने से काले क्रॉस को देखें।', 'ಸ್ಪಷ್ಟತೆ ಅಳೆಯಲು ಪ್ರತಿ ಮಾದರಿಯ ಮೂಲಕ ಕಪ್ಪು ಅಡ್ಡಗುರುತು ನೋಡಿ.'),
               W('Shake each with soap solution, and test with AgNO₃ for chloride.', 'प्रत्येक को साबुन विलयन के साथ हिलाएँ, और क्लोराइड के लिए AgNO₃ से परीक्षण करें।', 'ಪ್ರತಿಯೊಂದನ್ನು ಸಾಬೂನು ದ್ರಾವಣದೊಂದಿಗೆ ಅಲುಗಾಡಿಸಿ, ಕ್ಲೋರೈಡ್‌ಗೆ AgNO₃ ನಿಂದ ಪರೀಕ್ಷಿಸಿ.'),
               W('Tabulate the results site by site and compare.', 'परिणामों को स्थानवार सारणीबद्ध करें और तुलना करें।', 'ಫಲಿತಾಂಶಗಳನ್ನು ಸ್ಥಳವಾರು ಕೋಷ್ಟಕ ಮಾಡಿ ಹೋಲಿಸಿ.')],
        precautions=[W('Collect samples in clean, labelled bottles.', 'नमूने साफ़, नामांकित बोतलों में लें।', 'ಮಾದರಿಗಳನ್ನು ಸ್ವಚ್ಛ, ಲೇಬಲ್ ಹಾಕಿದ ಬಾಟಲಿಗಳಲ್ಲಿ ಸಂಗ್ರಹಿಸಿ.'), W('Use the same volume of sample and indicator each time.', 'हर बार नमूने और सूचक का समान आयतन लें।', 'ಪ್ರತಿ ಬಾರಿ ಮಾದರಿ ಮತ್ತು ಸೂಚಕದ ಒಂದೇ ಘನಫಲ ಬಳಸಿ.')],
        conclusion=W('The sites differ: tap water is clear and neutral, pond water turbid and slightly acidic, borewell water hard and alkaline; garden soil is acidic and roadside soil alkaline.', 'स्थान भिन्न हैं: नल का जल स्वच्छ और उदासीन, तालाब का जल गंदला और थोड़ा अम्लीय, बोरवेल का जल कठोर और क्षारीय; बगीचे की मिट्टी अम्लीय और सड़क किनारे की मिट्टी क्षारीय है।', 'ಸ್ಥಳಗಳು ಭಿನ್ನ: ನಲ್ಲಿ ನೀರು ಸ್ಪಷ್ಟ ಮತ್ತು ತಟಸ್ಥ, ಕೊಳದ ನೀರು ಮಸುಕು ಮತ್ತು ಸ್ವಲ್ಪ ಆಮ್ಲೀಯ, ಕೊಳವೆ ಬಾವಿ ನೀರು ಗಡಸು ಮತ್ತು ಕ್ಷಾರೀಯ; ತೋಟದ ಮಣ್ಣು ಆಮ್ಲೀಯ, ರಸ್ತೆಬದಿ ಮಣ್ಣು ಕ್ಷಾರೀಯ.'),
        viva=[Q(W('What is the pH of pure water?', 'शुद्ध जल का pH क्या है?', 'ಶುದ್ಧ ನೀರಿನ pH ಎಷ್ಟು?'), W('7 at 25 °C.', '25 °C पर 7.', '25 °C ನಲ್ಲಿ 7.')),
              Q(W('Why does turbid water harm aquatic plants?', 'गंदला जल जलीय पौधों को हानि क्यों पहुँचाता है?', 'ಮಸುಕು ನೀರು ಜಲಸಸ್ಯಗಳಿಗೆ ಏಕೆ ಹಾನಿಕರ?'), W('It cuts off light, so photosynthesis falls.', 'यह प्रकाश रोकता है, इसलिए प्रकाश-संश्लेषण घटता है।', 'ಅದು ಬೆಳಕನ್ನು ತಡೆಯುತ್ತದೆ, ಹಾಗಾಗಿ ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆ ಕಡಿಮೆ.')),
              Q(W('What makes water hard?', 'जल को कठोर क्या बनाता है?', 'ನೀರನ್ನು ಗಡಸಾಗಿಸುವುದು ಯಾವುದು?'), W('Dissolved calcium and magnesium salts.', 'घुले कैल्सियम और मैग्नीशियम लवण।', 'ಕರಗಿದ ಕ್ಯಾಲ್ಸಿಯಂ ಮತ್ತು ಮೆಗ್ನೀಸಿಯಂ ಲವಣಗಳು.')),
              Q(W('How is acidic soil corrected?', 'अम्लीय मिट्टी को कैसे सुधारते हैं?', 'ಆಮ್ಲೀಯ ಮಣ್ಣನ್ನು ಹೇಗೆ ಸರಿಪಡಿಸುತ್ತಾರೆ?'), W('By adding lime (calcium carbonate or calcium hydroxide).', 'चूना (कैल्सियम कार्बोनेट या कैल्सियम हाइड्रॉक्साइड) मिलाकर।', 'ಸುಣ್ಣ (ಕ್ಯಾಲ್ಸಿಯಂ ಕಾರ್ಬೊನೇಟ್ ಅಥವಾ ಹೈಡ್ರಾಕ್ಸೈಡ್) ಸೇರಿಸಿ.')),
              Q(W('Why might roadside soil be alkaline?', 'सड़क किनारे की मिट्टी क्षारीय क्यों हो सकती है?', 'ರಸ್ತೆಬದಿ ಮಣ್ಣು ಏಕೆ ಕ್ಷಾರೀಯವಾಗಿರಬಹುದು?'), W('Cement and lime dust and building debris wash into it.', 'सीमेंट और चूने की धूल और भवन मलबा उसमें बहकर आते हैं।', 'ಸಿಮೆಂಟ್, ಸುಣ್ಣದ ಧೂಳು ಮತ್ತು ಕಟ್ಟಡ ತ್ಯಾಜ್ಯ ಅದರಲ್ಲಿ ಸೇರುತ್ತವೆ.'))])

    # ------------------------------------------------------------ physiology
    lab(id='plasmolysis', bench='plasmolysis', **puc1,
        keywords=['transport in plants', 'plasmolysis', 'osmosis', 'water potential', 'osmotic potential', 'rhoeo', 'cell the unit of life', 'incipient plasmolysis'],
        title=W('Plasmolysis in Rhoeo leaf cells', 'रियो पत्ती कोशिकाओं में जीवद्रव्यकुंचन', 'ರಿಯೋ ಎಲೆ ಕೋಶಗಳಲ್ಲಿ ಜೀವದ್ರವ್ಯ ಕುಗ್ಗುವಿಕೆ'),
        summary=W('Mount Rhoeo peels in salt solutions of rising strength, count plasmolysed cells and find the strength that plasmolyses half of them.', 'रियो छिलकों को बढ़ती सांद्रता के लवण विलयनों में रखें, जीवद्रव्यकुंचित कोशिकाएँ गिनें और वह सांद्रता ज्ञात करें जो आधी कोशिकाओं को कुंचित करे।', 'ರಿಯೋ ಸಿಪ್ಪೆಗಳನ್ನು ಏರುತ್ತಿರುವ ಸಾಂದ್ರತೆಯ ಉಪ್ಪಿನ ದ್ರಾವಣಗಳಲ್ಲಿ ಇಟ್ಟು ಕುಗ್ಗಿದ ಕೋಶಗಳನ್ನು ಎಣಿಸಿ, ಅರ್ಧ ಕೋಶಗಳನ್ನು ಕುಗ್ಗಿಸುವ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To study plasmolysis in epidermal peels of Rhoeo and to find the osmotic potential of the cell sap by incipient plasmolysis.', 'रियो के बाह्यत्वचा छिलकों में जीवद्रव्यकुंचन का अध्ययन करना और आरंभिक जीवद्रव्यकुंचन द्वारा कोशिका रस का परासरण विभव ज्ञात करना।', 'ರಿಯೋದ ಹೊರಚರ್ಮ ಸಿಪ್ಪೆಗಳಲ್ಲಿ ಜೀವದ್ರವ್ಯ ಕುಗ್ಗುವಿಕೆ ಅಧ್ಯಯನ ಮಾಡಿ, ಆರಂಭಿಕ ಕುಗ್ಗುವಿಕೆಯಿಂದ ಕೋಶರಸದ ಅಭಿಸರಣ ವಿಭವ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('In a hypertonic solution water leaves the cell by osmosis and the protoplast shrinks away from the wall (plasmolysis). When half the cells are plasmolysed (incipient plasmolysis), the solution is isotonic with the cell sap: ψs = −iCRT.', 'अतिपरासारी विलयन में पानी परासरण द्वारा कोशिका से निकलता है और जीवद्रव्य भित्ति से सिकुड़ जाता है (जीवद्रव्यकुंचन)। जब आधी कोशिकाएँ कुंचित हों (आरंभिक जीवद्रव्यकुंचन), तब विलयन कोशिका रस के समपरासारी होता है: ψs = −iCRT.', 'ಅಧಿಕಸಾರ ದ್ರಾವಣದಲ್ಲಿ ನೀರು ಅಭಿಸರಣದಿಂದ ಕೋಶದಿಂದ ಹೊರಹೋಗಿ ಜೀವದ್ರವ್ಯ ಗೋಡೆಯಿಂದ ಕುಗ್ಗುತ್ತದೆ (ಕುಗ್ಗುವಿಕೆ). ಅರ್ಧ ಕೋಶಗಳು ಕುಗ್ಗಿದಾಗ (ಆರಂಭಿಕ ಕುಗ್ಗುವಿಕೆ), ದ್ರಾವಣ ಕೋಶರಸಕ್ಕೆ ಸಮಸಾರ: ψs = −iCRT.'),
        apparatus=[MICRO, W('Rhoeo leaves, forceps and needles', 'रियो पत्तियाँ, चिमटी और सुइयाँ', 'ರಿಯೋ ಎಲೆಗಳು, ಚಿಮುಟ ಮತ್ತು ಸೂಜಿಗಳು'), W('NaCl solutions 0.05–0.5 M', 'NaCl विलयन 0.05–0.5 M', 'NaCl ದ್ರಾವಣಗಳು 0.05–0.5 M'), W('Slides, cover slips and watch glasses', 'स्लाइडें, कवर स्लिप और वॉच ग्लास', 'ಸ್ಲೈಡ್‌ಗಳು, ಕವರ್ ಸ್ಲಿಪ್‌ಗಳು ಮತ್ತು ವಾಚ್ ಗ್ಲಾಸ್‌ಗಳು')],
        steps=[W('Peel the purple lower epidermis of a Rhoeo leaf and mount a piece in water: the cells are turgid.', 'रियो पत्ती की बैंगनी निचली बाह्यत्वचा छीलें और एक टुकड़ा पानी में रखें: कोशिकाएँ स्फीत हैं।', 'ರಿಯೋ ಎಲೆಯ ನೇರಳೆ ಕೆಳ ಹೊರಚರ್ಮ ಸುಲಿದು ಒಂದು ತುಂಡನ್ನು ನೀರಿನಲ್ಲಿ ಇಡಿ: ಕೋಶಗಳು ಉಬ್ಬಿವೆ.'),
               W('Place pieces in NaCl solutions of rising strength for 10 minutes.', 'टुकड़ों को बढ़ती सांद्रता के NaCl विलयनों में 10 मिनट रखें।', 'ತುಂಡುಗಳನ್ನು ಏರುತ್ತಿರುವ ಸಾಂದ್ರತೆಯ NaCl ದ್ರಾವಣಗಳಲ್ಲಿ 10 ನಿಮಿಷ ಇಡಿ.'),
               W('Mount each in its own solution and count plasmolysed cells in a field.', 'प्रत्येक को उसी के विलयन में रखें और एक क्षेत्र में कुंचित कोशिकाएँ गिनें।', 'ಪ್ರತಿಯೊಂದನ್ನು ಅದರದೇ ದ್ರಾವಣದಲ್ಲಿ ಇಟ್ಟು ಒಂದು ಕ್ಷೇತ್ರದಲ್ಲಿ ಕುಗ್ಗಿದ ಕೋಶಗಳನ್ನು ಎಣಿಸಿ.'),
               W('Plot % plasmolysed against concentration and read where it crosses 50%.', '% कुंचित और सांद्रता का ग्राफ़ बनाएँ और देखें कि वह 50% को कहाँ पार करता है।', '% ಕುಗ್ಗಿದ ಮತ್ತು ಸಾಂದ್ರತೆಯ ನಕ್ಷೆ ಎಳೆದು ಅದು 50% ದಾಟುವಲ್ಲಿ ಓದಿ.'),
               W('Put a plasmolysed peel back in water and watch it recover (deplasmolysis).', 'कुंचित छिलके को वापस पानी में रखें और उसे पुनः स्फीत होते देखें (विजीवद्रव्यकुंचन)।', 'ಕುಗ್ಗಿದ ಸಿಪ್ಪೆಯನ್ನು ಮತ್ತೆ ನೀರಿನಲ್ಲಿಟ್ಟು ಅದು ಚೇತರಿಸುವುದನ್ನು ನೋಡಿ (ಪುನರುಬ್ಬುವಿಕೆ).')],
        precautions=[W('Use single-layered peels so cells are clearly seen.', 'एक परत वाले छिलके लें ताकि कोशिकाएँ स्पष्ट दिखें।', 'ಕೋಶಗಳು ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣಲು ಒಂದೇ ಪದರದ ಸಿಪ್ಪೆ ಬಳಸಿ.'), W('Mount each peel in the same solution it was kept in.', 'प्रत्येक छिलके को उसी विलयन में रखें जिसमें वह रखा गया था।', 'ಪ್ರತಿ ಸಿಪ್ಪೆಯನ್ನು ಅದನ್ನಿಟ್ಟ ದ್ರಾವಣದಲ್ಲೇ ಇಡಿ.'), W('Count the same number of cells in each field.', 'हर क्षेत्र में समान संख्या में कोशिकाएँ गिनें।', 'ಪ್ರತಿ ಕ್ಷೇತ್ರದಲ್ಲಿ ಒಂದೇ ಸಂಖ್ಯೆಯ ಕೋಶಗಳನ್ನು ಎಣಿಸಿ.')],
        conclusion=W('Cells plasmolyse in hypertonic salt and recover in water; half are plasmolysed near 0.18 M NaCl, so the cell sap’s osmotic potential is about −0.9 MPa.', 'कोशिकाएँ अतिपरासारी लवण में कुंचित होती हैं और पानी में पुनः स्फीत होती हैं; लगभग 0.18 M NaCl पर आधी कुंचित होती हैं, अतः कोशिका रस का परासरण विभव लगभग −0.9 MPa है।', 'ಕೋಶಗಳು ಅಧಿಕಸಾರ ಉಪ್ಪಿನಲ್ಲಿ ಕುಗ್ಗಿ ನೀರಿನಲ್ಲಿ ಚೇತರಿಸುತ್ತವೆ; ಸುಮಾರು 0.18 M NaCl ನಲ್ಲಿ ಅರ್ಧ ಕುಗ್ಗುತ್ತವೆ, ಹಾಗಾಗಿ ಕೋಶರಸದ ಅಭಿಸರಣ ವಿಭವ ಸುಮಾರು −0.9 MPa.'),
        viva=[Q(W('Why are Rhoeo peels used?', 'रियो छिलके क्यों उपयोग होते हैं?', 'ರಿಯೋ ಸಿಪ್ಪೆಗಳನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?'), W('Their coloured cell sap makes the shrinking protoplast easy to see.', 'उनका रंगीन कोशिका रस सिकुड़ते जीवद्रव्य को आसानी से दिखाता है।', 'ಅವುಗಳ ಬಣ್ಣದ ಕೋಶರಸ ಕುಗ್ಗುವ ಜೀವದ್ರವ್ಯವನ್ನು ಸುಲಭವಾಗಿ ತೋರಿಸುತ್ತದೆ.')),
              Q(W('What fills the space between wall and protoplast after plasmolysis?', 'जीवद्रव्यकुंचन के बाद भित्ति और जीवद्रव्य के बीच क्या भरता है?', 'ಕುಗ್ಗುವಿಕೆಯ ನಂತರ ಗೋಡೆ ಮತ್ತು ಜೀವದ್ರವ್ಯದ ನಡುವೆ ಏನು ತುಂಬುತ್ತದೆ?'), W('The outside solution, because the cell wall is freely permeable.', 'बाहरी विलयन, क्योंकि कोशिका भित्ति पूर्णतः पारगम्य है।', 'ಹೊರಗಿನ ದ್ರಾವಣ, ಏಕೆಂದರೆ ಕೋಶ ಗೋಡೆ ಮುಕ್ತವಾಗಿ ಪ್ರವೇಶ್ಯ.')),
              Q(W('What is a hypertonic solution?', 'अतिपरासारी विलयन क्या है?', 'ಅಧಿಕಸಾರ ದ್ರಾವಣ ಎಂದರೇನು?'), W('One more concentrated than the cell sap (lower water potential).', 'जो कोशिका रस से अधिक सांद्र हो (कम जल विभव)।', 'ಕೋಶರಸಕ್ಕಿಂತ ಹೆಚ್ಚು ಸಾಂದ್ರ (ಕಡಿಮೆ ಜಲ ವಿಭವ).')),
              Q(W('Why is i = 2 for NaCl?', 'NaCl के लिए i = 2 क्यों है?', 'NaCl ಗೆ i = 2 ಏಕೆ?'), W('It splits into two ions, Na⁺ and Cl⁻.', 'यह दो आयनों, Na⁺ और Cl⁻, में टूटता है।', 'ಅದು Na⁺ ಮತ್ತು Cl⁻ ಎಂಬ ಎರಡು ಅಯಾನುಗಳಾಗಿ ಒಡೆಯುತ್ತದೆ.')),
              Q(W('Why does salting pickles preserve them?', 'अचार में नमक डालने से वह सुरक्षित क्यों रहता है?', 'ಉಪ್ಪಿನಕಾಯಿಗೆ ಉಪ್ಪು ಹಾಕುವುದರಿಂದ ಅದು ಏಕೆ ಕೆಡುವುದಿಲ್ಲ?'), W('Microbes are plasmolysed and cannot grow.', 'सूक्ष्मजीव कुंचित हो जाते हैं और बढ़ नहीं पाते।', 'ಸೂಕ್ಷ್ಮಜೀವಿಗಳು ಕುಗ್ಗಿ ಬೆಳೆಯಲಾರವು.'))])

    lab(id='respiration-rq', bench='respiration', **puc1,
        keywords=['respiration in plants', 'respiratory quotient', 'respirometer', 'germinating seeds', 'rq', 'oxygen uptake', 'aerobic respiration'],
        title=W('Rate of respiration and respiratory quotient', 'श्वसन दर और श्वसन गुणांक', 'ಉಸಿರಾಟದ ದರ ಮತ್ತು ಉಸಿರಾಟದ ಅಂಶ'),
        summary=W('Measure the oxygen taken in by germinating seeds or flower buds in a respirometer, with and without KOH, and find the RQ.', 'श्वसनमापी में अंकुरित बीजों या कलियों द्वारा ली गई ऑक्सीजन KOH सहित और रहित मापें और RQ ज्ञात करें।', 'ಉಸಿರಾಟಮಾಪಕದಲ್ಲಿ ಮೊಳಕೆ ಬೀಜಗಳು ಅಥವಾ ಹೂ ಮೊಗ್ಗುಗಳು ತೆಗೆದುಕೊಳ್ಳುವ ಆಮ್ಲಜನಕವನ್ನು KOH ಸಹಿತ ಮತ್ತು ರಹಿತ ಅಳೆದು RQ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To study the rate of respiration in germinating seeds and flower buds and to find their respiratory quotient.', 'अंकुरित बीजों और पुष्प कलियों में श्वसन दर का अध्ययन करना और उनका श्वसन गुणांक ज्ञात करना।', 'ಮೊಳಕೆ ಬೀಜಗಳು ಮತ್ತು ಹೂ ಮೊಗ್ಗುಗಳಲ್ಲಿ ಉಸಿರಾಟದ ದರ ಅಧ್ಯಯನ ಮಾಡಿ ಅವುಗಳ ಉಸಿರಾಟದ ಅಂಶ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('RQ = CO₂ released ÷ O₂ taken in. With KOH absorbing CO₂, the drop moves by the O₂ used (x); without KOH, by O₂ − CO₂ (y). So RQ = (x − y)/x: about 1 for carbohydrates and about 0.7 for fats.', 'RQ = मुक्त CO₂ ÷ ली गई O₂. KOH द्वारा CO₂ अवशोषित होने पर बूँद प्रयुक्त O₂ (x) जितनी चलती है; KOH के बिना O₂ − CO₂ (y) जितनी। अतः RQ = (x − y)/x: कार्बोहाइड्रेट के लिए लगभग 1 और वसा के लिए लगभग 0.7.', 'RQ = ಬಿಡುಗಡೆಯಾದ CO₂ ÷ ತೆಗೆದುಕೊಂಡ O₂. KOH CO₂ ಹೀರಿದಾಗ ಹನಿ ಬಳಸಿದ O₂ (x) ನಷ್ಟು ಚಲಿಸುತ್ತದೆ; KOH ಇಲ್ಲದೆ O₂ − CO₂ (y) ನಷ್ಟು. ಹಾಗಾಗಿ RQ = (x − y)/x: ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌ಗೆ ಸುಮಾರು 1, ಕೊಬ್ಬಿಗೆ ಸುಮಾರು 0.7.'),
        apparatus=[W('Respirometer (boiling tube with a graduated capillary)', 'श्वसनमापी (अंशांकित केशिका सहित क्वथन नली)', 'ಉಸಿರಾಟಮಾಪಕ (ಅಂಶಾಂಕಿತ ಲೋಮನಾಳ ಸಹಿತ ಕುದಿ ನಳಿಕೆ)'), W('Germinating wheat and castor seeds, flower buds', 'अंकुरित गेहूँ और अरंडी के बीज, पुष्प कलियाँ', 'ಮೊಳಕೆಯೊಡೆದ ಗೋಧಿ ಮತ್ತು ಹರಳು ಬೀಜಗಳು, ಹೂ ಮೊಗ್ಗುಗಳು'), W('KOH pellets and cotton', 'KOH गोलियाँ और रूई', 'KOH ಗುಳಿಗೆಗಳು ಮತ್ತು ಹತ್ತಿ'), W('Coloured water and a stopwatch', 'रंगीन पानी और विराम घड़ी', 'ಬಣ್ಣದ ನೀರು ಮತ್ತು ನಿಲುಗಡಿಯಾರ')],
        steps=[W('Put the seeds in the tube with KOH pellets in a small tube held by cotton; fit the cork and capillary.', 'बीजों को नली में रखें और KOH गोलियाँ रूई से थमी छोटी नली में; कॉर्क और केशिका लगाएँ।', 'ಬೀಜಗಳನ್ನು ನಳಿಕೆಯಲ್ಲಿ, KOH ಗುಳಿಗೆಗಳನ್ನು ಹತ್ತಿಯಿಂದ ಹಿಡಿದ ಸಣ್ಣ ನಳಿಕೆಯಲ್ಲಿ ಇಡಿ; ಕಾರ್ಕ್ ಮತ್ತು ಲೋಮನಾಳ ಜೋಡಿಸಿ.'),
               W('Introduce a drop of coloured water into the capillary and note its position.', 'केशिका में रंगीन पानी की एक बूँद डालें और उसकी स्थिति लिखें।', 'ಲೋಮನಾಳಕ್ಕೆ ಬಣ್ಣದ ನೀರಿನ ಒಂದು ಹನಿ ಸೇರಿಸಿ ಅದರ ಸ್ಥಾನ ಬರೆಯಿರಿ.'),
               W('Read the distance it moves every 5 minutes.', 'हर 5 मिनट में उसके चली दूरी पढ़ें।', 'ಪ್ರತಿ 5 ನಿಮಿಷಕ್ಕೆ ಅದು ಚಲಿಸಿದ ದೂರ ಓದಿ.'),
               W('Repeat without KOH.', 'KOH के बिना दोहराएँ।', 'KOH ಇಲ್ಲದೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Convert distances to volumes and work out RQ = (x − y)/x; repeat for castor seeds and buds.', 'दूरियों को आयतन में बदलें और RQ = (x − y)/x निकालें; अरंडी के बीजों और कलियों के लिए दोहराएँ।', 'ದೂರಗಳನ್ನು ಘನಫಲಕ್ಕೆ ಪರಿವರ್ತಿಸಿ RQ = (x − y)/x ಲೆಕ್ಕಿಸಿ; ಹರಳು ಬೀಜ ಮತ್ತು ಮೊಗ್ಗುಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Make the apparatus airtight; seal the cork with wax.', 'उपकरण वायुरुद्ध करें; कॉर्क को मोम से बंद करें।', 'ಉಪಕರಣವನ್ನು ಗಾಳಿಯಾಡದಂತೆ ಮಾಡಿ; ಕಾರ್ಕನ್ನು ಮೇಣದಿಂದ ಮುಚ್ಚಿ.'), W('Keep the temperature constant: hold the tube in a water bath, not in your hand.', 'ताप स्थिर रखें: नली को हाथ में नहीं, जल ऊष्मक में रखें।', 'ತಾಪ ಸ್ಥಿರವಾಗಿಡಿ: ನಳಿಕೆಯನ್ನು ಕೈಯಲ್ಲಲ್ಲ, ನೀರಿನ ಸ್ನಾನಪಾತ್ರೆಯಲ್ಲಿ ಇಡಿ.'), W('KOH is caustic: do not touch the pellets.', 'KOH दाहक है: गोलियों को न छुएँ।', 'KOH ದಾಹಕ: ಗುಳಿಗೆಗಳನ್ನು ಮುಟ್ಟಬೇಡಿ.')],
        conclusion=W('Wheat seeds and flower buds give an RQ near 1 (carbohydrate is respired); castor seeds give about 0.7 (fat is respired).', 'गेहूँ के बीज और पुष्प कलियाँ लगभग 1 RQ देती हैं (कार्बोहाइड्रेट का श्वसन); अरंडी के बीज लगभग 0.7 देते हैं (वसा का श्वसन)।', 'ಗೋಧಿ ಬೀಜಗಳು ಮತ್ತು ಹೂ ಮೊಗ್ಗುಗಳು ಸುಮಾರು 1 RQ ನೀಡುತ್ತವೆ (ಕಾರ್ಬೋಹೈಡ್ರೇಟ್ ಉಸಿರಾಟ); ಹರಳು ಬೀಜಗಳು ಸುಮಾರು 0.7 (ಕೊಬ್ಬು ಉಸಿರಾಟ).'),
        viva=[Q(W('What is the RQ of glucose?', 'ग्लूकोज़ का RQ क्या है?', 'ಗ್ಲೂಕೋಸ್‌ನ RQ ಎಷ್ಟು?'), W('1: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', '1: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.', '1: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O.')),
              Q(W('Why is the RQ of fats less than 1?', 'वसा का RQ 1 से कम क्यों है?', 'ಕೊಬ್ಬಿನ RQ 1 ಕ್ಕಿಂತ ಕಡಿಮೆ ಏಕೆ?'), W('Fats contain little oxygen, so they need more O₂ than the CO₂ they give.', 'वसा में ऑक्सीजन कम होती है, इसलिए वे जितनी CO₂ देते हैं उससे अधिक O₂ लेते हैं।', 'ಕೊಬ್ಬಿನಲ್ಲಿ ಆಮ್ಲಜನಕ ಕಡಿಮೆ, ಹಾಗಾಗಿ ಕೊಡುವ CO₂ ಗಿಂತ ಹೆಚ್ಚು O₂ ಬೇಕು.')),
              Q(W('What does KOH do in the respirometer?', 'श्वसनमापी में KOH क्या करता है?', 'ಉಸಿರಾಟಮಾಪಕದಲ್ಲಿ KOH ಏನು ಮಾಡುತ್ತದೆ?'), W('It absorbs the CO₂ given out.', 'यह निकली CO₂ को अवशोषित करता है।', 'ಬಿಡುಗಡೆಯಾದ CO₂ ಅನ್ನು ಹೀರುತ್ತದೆ.')),
              Q(W('What is the RQ during anaerobic respiration?', 'अवायवीय श्वसन में RQ क्या होता है?', 'ಆಮ್ಲಜನಕರಹಿತ ಉಸಿರಾಟದಲ್ಲಿ RQ ಎಷ್ಟು?'), W('Infinite: CO₂ is released with no O₂ taken in.', 'अनंत: बिना O₂ लिए CO₂ मुक्त होती है।', 'ಅನಂತ: O₂ ತೆಗೆದುಕೊಳ್ಳದೆ CO₂ ಬಿಡುಗಡೆಯಾಗುತ್ತದೆ.')),
              Q(W('Why do germinating seeds respire fast?', 'अंकुरित बीज तेज़ी से श्वसन क्यों करते हैं?', 'ಮೊಳಕೆ ಬೀಜಗಳು ವೇಗವಾಗಿ ಉಸಿರಾಡುವುದೇಕೆ?'), W('Growth needs a lot of energy from stored food.', 'वृद्धि के लिए संचित भोजन से बहुत ऊर्जा चाहिए।', 'ಬೆಳವಣಿಗೆಗೆ ಸಂಗ್ರಹಿತ ಆಹಾರದಿಂದ ಹೆಚ್ಚು ಶಕ್ತಿ ಬೇಕು.'))])

    lab(id='quadrat-study', bench='quadrat', **puc2,
        keywords=['organisms and populations', 'quadrat', 'population density', 'frequency', 'abundance', 'ecology', 'biodiversity and conservation', 'sampling'],
        title=W('Population density and frequency by the quadrat method', 'क्वाड्रैट विधि से समष्टि घनत्व और आवृत्ति', 'ಕ್ವಾಡ್ರಾಟ್ ವಿಧಾನದಿಂದ ಜನಸಂಖ್ಯಾ ಸಾಂದ್ರತೆ ಮತ್ತು ಆವರ್ತನ'),
        summary=W('Throw a 1 m quadrat at random ten times in a plot, count each plant species, and work out density, frequency and abundance.', 'एक भूखंड में 1 m क्वाड्रैट को यादृच्छिक रूप से दस बार फेंकें, हर पादप जाति गिनें और घनत्व, आवृत्ति और बहुलता निकालें।', 'ಒಂದು ಪ್ಲಾಟ್‌ನಲ್ಲಿ 1 m ಕ್ವಾಡ್ರಾಟನ್ನು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಹತ್ತು ಬಾರಿ ಎಸೆದು, ಪ್ರತಿ ಸಸ್ಯ ಪ್ರಭೇದ ಎಣಿಸಿ ಸಾಂದ್ರತೆ, ಆವರ್ತನ ಮತ್ತು ಸಮೃದ್ಧಿ ಲೆಕ್ಕಿಸಿ.'),
        aim=W('To study the population density, frequency and abundance of plant species by the quadrat method.', 'क्वाड्रैट विधि से पादप जातियों के समष्टि घनत्व, आवृत्ति और बहुलता का अध्ययन करना।', 'ಕ್ವಾಡ್ರಾಟ್ ವಿಧಾನದಿಂದ ಸಸ್ಯ ಪ್ರಭೇದಗಳ ಜನಸಂಖ್ಯಾ ಸಾಂದ್ರತೆ, ಆವರ್ತನ ಮತ್ತು ಸಮೃದ್ಧಿ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Counting every plant is impractical, so random samples are counted. Density = total individuals ÷ number of quadrats; frequency = quadrats with the species ÷ quadrats studied × 100; abundance = total individuals ÷ quadrats in which it occurs.', 'हर पौधा गिनना अव्यावहारिक है, इसलिए यादृच्छिक नमूने गिने जाते हैं। घनत्व = कुल सदस्य ÷ क्वाड्रैट संख्या; आवृत्ति = जाति वाले क्वाड्रैट ÷ अध्ययन किए क्वाड्रैट × 100; बहुलता = कुल सदस्य ÷ जिन क्वाड्रैटों में वह मिली।', 'ಪ್ರತಿ ಸಸ್ಯ ಎಣಿಸುವುದು ಅಸಾಧ್ಯ; ಹಾಗಾಗಿ ಯಾದೃಚ್ಛಿಕ ಮಾದರಿಗಳನ್ನು ಎಣಿಸಲಾಗುತ್ತದೆ. ಸಾಂದ್ರತೆ = ಒಟ್ಟು ಸದಸ್ಯರು ÷ ಕ್ವಾಡ್ರಾಟ್‌ಗಳ ಸಂಖ್ಯೆ; ಆವರ್ತನ = ಪ್ರಭೇದವಿರುವ ಕ್ವಾಡ್ರಾಟ್‌ಗಳು ÷ ಅಧ್ಯಯನಿಸಿದ ಕ್ವಾಡ್ರಾಟ್‌ಗಳು × 100; ಸಮೃದ್ಧಿ = ಒಟ್ಟು ಸದಸ್ಯರು ÷ ಅದು ಕಂಡ ಕ್ವಾಡ್ರಾಟ್‌ಗಳು.'),
        apparatus=[W('1 m × 1 m quadrat frame', '1 m × 1 m क्वाड्रैट फ्रेम', '1 m × 1 m ಕ್ವಾಡ್ರಾಟ್ ಚೌಕಟ್ಟು'), W('Measuring tape and pegs', 'मापने का फीता और खूँटियाँ', 'ಅಳತೆ ಟೇಪ್ ಮತ್ತು ಗೂಟಗಳು'), W('Field notebook', 'क्षेत्र नोटबुक', 'ಕ್ಷೇತ್ರ ಟಿಪ್ಪಣಿ ಪುಸ್ತಕ')],
        steps=[W('Mark out the study plot with pegs and tape.', 'खूँटियों और फीते से अध्ययन भूखंड चिह्नित करें।', 'ಗೂಟ ಮತ್ತು ಟೇಪ್‌ನಿಂದ ಅಧ್ಯಯನ ಪ್ಲಾಟ್ ಗುರುತಿಸಿ.'),
               W('Throw the quadrat at random (eyes closed, over the shoulder).', 'क्वाड्रैट को यादृच्छिक रूप से फेंकें (आँखें बंद, कंधे के ऊपर से)।', 'ಕ್ವಾಡ್ರಾಟನ್ನು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಎಸೆಯಿರಿ (ಕಣ್ಣು ಮುಚ್ಚಿ, ಭುಜದ ಮೇಲಿಂದ).'),
               W('Count the plants of each species inside it; count those on the edge on two sides only.', 'उसके अंदर हर जाति के पौधे गिनें; किनारे वालों को केवल दो भुजाओं पर गिनें।', 'ಅದರೊಳಗಿನ ಪ್ರತಿ ಪ್ರಭೇದದ ಸಸ್ಯ ಎಣಿಸಿ; ಅಂಚಿನವುಗಳನ್ನು ಎರಡು ಬದಿಗಳಲ್ಲಿ ಮಾತ್ರ ಎಣಿಸಿ.'),
               W('Repeat for at least ten quadrats.', 'कम से कम दस क्वाड्रैटों के लिए दोहराएँ।', 'ಕನಿಷ್ಠ ಹತ್ತು ಕ್ವಾಡ್ರಾಟ್‌ಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Work out the density, frequency and abundance of each species.', 'हर जाति का घनत्व, आवृत्ति और बहुलता निकालें।', 'ಪ್ರತಿ ಪ್ರಭೇದದ ಸಾಂದ್ರತೆ, ಆವರ್ತನ ಮತ್ತು ಸಮೃದ್ಧಿ ಲೆಕ್ಕಿಸಿ.')],
        precautions=[W('Throw the quadrat truly at random; do not choose spots.', 'क्वाड्रैट वास्तव में यादृच्छिक फेंकें; स्थान न चुनें।', 'ಕ್ವಾಡ್ರಾಟನ್ನು ನಿಜವಾಗಿ ಯಾದೃಚ್ಛಿಕವಾಗಿ ಎಸೆಯಿರಿ; ಸ್ಥಳ ಆರಿಸಬೇಡಿ.'), W('Identify species carefully before counting.', 'गिनने से पहले जातियों की ध्यान से पहचान करें।', 'ಎಣಿಸುವ ಮೊದಲು ಪ್ರಭೇದಗಳನ್ನು ಜಾಗ್ರತೆಯಿಂದ ಗುರುತಿಸಿ.'), W('Use enough quadrats for a fair sample.', 'उचित नमूने के लिए पर्याप्त क्वाड्रैट लें।', 'ನ್ಯಾಯಯುತ ಮಾದರಿಗೆ ಸಾಕಷ್ಟು ಕ್ವಾಡ್ರಾಟ್ ಬಳಸಿ.')],
        conclusion=W('Cynodon has the highest density and frequency in the plot; Parthenium the lowest. A species can be abundant where it grows yet infrequent, if it grows in patches.', 'भूखंड में साइनोडॉन का घनत्व और आवृत्ति सबसे अधिक है; पार्थेनियम का सबसे कम। कोई जाति टुकड़ों में उगे तो जहाँ उगे वहाँ बहुल पर कम आवृत्ति वाली हो सकती है।', 'ಪ್ಲಾಟ್‌ನಲ್ಲಿ ಸೈನೋಡಾನ್‌ಗೆ ಅತಿ ಹೆಚ್ಚು ಸಾಂದ್ರತೆ ಮತ್ತು ಆವರ್ತನ; ಪಾರ್ಥೇನಿಯಂಗೆ ಅತಿ ಕಡಿಮೆ. ತೇಪೆಗಳಲ್ಲಿ ಬೆಳೆಯುವ ಪ್ರಭೇದ ಬೆಳೆದಲ್ಲಿ ಸಮೃದ್ಧವಾಗಿದ್ದು ಆವರ್ತನ ಕಡಿಮೆ ಇರಬಹುದು.'),
        viva=[Q(W('What is a quadrat?', 'क्वाड्रैट क्या है?', 'ಕ್ವಾಡ್ರಾಟ್ ಎಂದರೇನು?'), W('A square frame marking a sample area, usually 1 m² for herbs.', 'नमूना क्षेत्र चिह्नित करने वाला वर्गाकार फ्रेम, शाकों के लिए प्रायः 1 m²।', 'ಮಾದರಿ ಪ್ರದೇಶ ಗುರುತಿಸುವ ಚೌಕ ಚೌಕಟ್ಟು, ಮೂಲಿಕೆಗಳಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ 1 m².')),
              Q(W('Why are quadrats thrown at random?', 'क्वाड्रैट यादृच्छिक रूप से क्यों फेंके जाते हैं?', 'ಕ್ವಾಡ್ರಾಟ್‌ಗಳನ್ನು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಏಕೆ ಎಸೆಯುತ್ತಾರೆ?'), W('To avoid bias, so the sample represents the whole plot.', 'पक्षपात से बचने के लिए, ताकि नमूना पूरे भूखंड का प्रतिनिधित्व करे।', 'ಪಕ್ಷಪಾತ ತಪ್ಪಿಸಲು, ಮಾದರಿ ಪೂರ್ತಿ ಪ್ಲಾಟನ್ನು ಪ್ರತಿನಿಧಿಸಲು.')),
              Q(W('Define population density.', 'समष्टि घनत्व की परिभाषा दीजिए।', 'ಜನಸಂಖ್ಯಾ ಸಾಂದ್ರತೆ ವ್ಯಾಖ್ಯಾನಿಸಿ.'), W('The number of individuals per unit area.', 'प्रति इकाई क्षेत्र सदस्यों की संख्या।', 'ಏಕಮಾನ ಪ್ರದೇಶಕ್ಕೆ ಸದಸ್ಯರ ಸಂಖ್ಯೆ.')),
              Q(W('What does a frequency of 100% mean?', '100% आवृत्ति का क्या अर्थ है?', '100% ಆವರ್ತನ ಅರ್ಥವೇನು?'), W('The species was found in every quadrat.', 'जाति हर क्वाड्रैट में मिली।', 'ಪ್ರಭೇದ ಪ್ರತಿ ಕ್ವಾಡ್ರಾಟ್‌ನಲ್ಲಿ ಕಂಡುಬಂತು.')),
              Q(W('Why is Parthenium a concern?', 'पार्थेनियम चिंता का विषय क्यों है?', 'ಪಾರ್ಥೇನಿಯಂ ಏಕೆ ಆತಂಕಕಾರಿ?'), W('It is an invasive alien weed that spreads fast and causes allergies.', 'यह तेज़ी से फैलने वाली आक्रामक विदेशी खरपतवार है जो एलर्जी करती है।', 'ಅದು ವೇಗವಾಗಿ ಹರಡುವ ಆಕ್ರಮಣಕಾರಿ ವಿದೇಶಿ ಕಳೆ, ಅಲರ್ಜಿ ಉಂಟುಮಾಡುತ್ತದೆ.'))])
